import { z } from "zod";
import { CALENDAR_MAX_AGE_MS, deriveSeasonContext, type SeasonPhase } from "./season-phase.js";
import type { EvidencePackage } from "./research.js";

export interface EvidenceRequirement { name: string; layer: "PRIMARY" | "CURRENT" | "MULTI_YEAR" | "POSTSEASON"; allowNotApplicable?: boolean }
const COMMON: EvidenceRequirement[] = [
  { name: "performance_summary", layer: "PRIMARY" },
  { name: "postseason_context", layer: "POSTSEASON", allowNotApplicable: true },
  { name: "multi_year_trend", layer: "MULTI_YEAR" },
  ...["current_role", "roster_depth_chart", "injury_practice_status", "age_career_trajectory", "team_system_context"]
    .map(name => ({ name, layer: "CURRENT" as const })),
  { name: "preseason_participation", layer: "CURRENT", allowNotApplicable: true },
  ...["durability_availability", "recent_performance_trend", "locked_control_comparisons", "outside_control_comparisons", "position_specific_traits"]
    .map(name => ({ name, layer: "PRIMARY" as const }))
];
const QB = ["passing_production_efficiency", "advanced_passing_metrics", "pressure_performance",
  "accuracy_by_depth", "turnover_worthy_mistakes", "rushing_designed_run_value", "scrambling_sack_avoidance"];

export function requiredEvidenceCategories(position: string, phase: SeasonPhase): EvidenceRequirement[] {
  return [...COMMON.map(item => ({ ...item })),
    ...(position === "QB" ? QB.map(name => ({ name, layer: "PRIMARY" as const })) : []),
    ...(!["OFFSEASON", "PRESEASON"].includes(phase) ? [{ name: "current_season_performance", layer: "CURRENT" as const }] : [])];
}

const instant = z.string().datetime({ offset: true });
export const evidenceCategorySchema = z.object({
  status: z.enum(["satisfied", "partial", "missing", "not_applicable"]),
  confidence: z.enum(["HIGH", "MEDIUM", "LOW"]),
  items: z.array(z.object({
    claim: z.string().trim().min(1), source_url: z.string().url(), retrieved_at: instant,
    season: z.number().int(), period: z.enum(["REGULAR_SEASON", "POSTSEASON", "CURRENT_CONTEXT"])
  })).min(1),
  limitations: z.array(z.string()),
  not_applicable_reason: z.string().trim().min(1).optional(),
  compared_controls: z.array(z.string()).optional()
});
const packageSchema = z.object({
  task_id: z.string(), position: z.string(), researched_at: instant,
  sources: z.array(z.object({ name: z.string().min(1), url: z.string().url(), retrieved_at: instant,
    published_at: z.string().nullable(), authority_tier: z.number().int().min(1).max(5), claims: z.array(z.string()) })).min(1),
  normalized: z.record(z.unknown()), conflicts: z.array(z.record(z.unknown())),
  minimum_evidence_met: z.boolean(), missing_evidence: z.array(z.string())
});

function controlNames(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.map(item => typeof item === "string" ? item : item?.player).filter((name): name is string => typeof name === "string");
}

// This gate never approves an audit, mutates its input, or writes project state.
export function applyFullAuditEvidenceGate(evidence: EvidencePackage, task: Record<string, unknown>, asOf: string): EvidencePackage {
  const context = deriveSeasonContext(evidence.calendar, asOf, task);
  const errors: string[] = [];
  const checked = packageSchema.safeParse(evidence);
  if (!checked.success) errors.push("INVALID_FULL_AUDIT_EVIDENCE_STRUCTURE");
  if (evidence.calendar_web_search_observed !== true) errors.push("FRESH_CALENDAR_RESEARCH_UNAVAILABLE");
  if (evidence.fresh_web_research_observed !== true) errors.push("fresh_web_research_unavailable");
  if (context.status !== "RESOLVED") errors.push(...context.errors);
  if (evidence.minimum_evidence_met !== true) errors.push("RESEARCHER_MINIMUM_EVIDENCE_NOT_MET");
  if (checked.success && context.status === "RESOLVED") {
    const data = checked.data;
    const metadata = context.metadata;
    if (data.task_id !== task.task_id || data.position !== task.position) errors.push("EVIDENCE_TASK_MISMATCH");
    if (!data.sources.some(source => source.authority_tier === 1 && source.claims.length)) errors.push("HIGH_AUTHORITY_EVIDENCE_MISSING");
    const sources = new Map(data.sources.map(source => [source.url, source]));
    const fresh = (time: string) => Date.parse(asOf) - Date.parse(time) >= 0 && Date.parse(asOf) - Date.parse(time) <= CALENDAR_MAX_AGE_MS;
    if (!fresh(data.researched_at)) errors.push("EVIDENCE_STALE_OR_FUTURE");
    const requirements = requiredEvidenceCategories(data.position, metadata.season_phase);
    for (const name of Object.keys(data.normalized)) {
      if (!requirements.some(requirement => requirement.name === name)) errors.push(`${name}: UNEXPECTED_UNCHECKED_CATEGORY`);
    }
    for (const requirement of requirements) {
      const category = evidenceCategorySchema.safeParse(data.normalized[requirement.name]);
      const fail = (reason: string) => errors.push(`${requirement.name}: ${reason}`);
      if (!category.success) { fail("MISSING_OR_INVALID_CATEGORY"); continue; }
      const value = category.data;
      const notApplicable = value.status === "not_applicable";
      if (value.status !== "satisfied" && !(notApplicable && requirement.allowNotApplicable && value.not_applicable_reason)) fail("CATEGORY_NOT_SATISFIED");
      if (value.confidence === "LOW") fail("LOW_CONFIDENCE_EVIDENCE");
      for (const item of value.items) {
        const source = sources.get(item.source_url);
        if (!source || !fresh(item.retrieved_at) || !fresh(source.retrieved_at)) fail("UNTRACEABLE_OR_STALE_ITEM");
        if (item.season > metadata.nfl_season) fail("FUTURE_SEASON_EVIDENCE");
        if (["OFFSEASON", "PRESEASON"].includes(metadata.season_phase) &&
          item.season === metadata.nfl_season && item.period === "REGULAR_SEASON") fail("NONEXISTENT_UPCOMING_REGULAR_SEASON_SAMPLE");
      }
      const expectedSeason = requirement.layer === "CURRENT" ? metadata.nfl_season : metadata.evidence_season;
      if (!value.items.some(item => item.season === expectedSeason)) fail("REQUIRED_SEASON_NOT_COVERED");
      if (!notApplicable) {
        if (requirement.layer === "PRIMARY" && !value.items.some(item => item.season === expectedSeason && item.period === "REGULAR_SEASON")) fail("PRIMARY_REGULAR_SEASON_SAMPLE_MISSING");
        if (requirement.layer === "POSTSEASON" && !value.items.some(item => item.season === expectedSeason && item.period === "POSTSEASON")) fail("POSTSEASON_SAMPLE_MISSING");
        if (requirement.layer === "MULTI_YEAR" && !value.items.some(item => item.season < expectedSeason)) fail("MULTI_YEAR_CONTEXT_MISSING");
        if (requirement.name === "current_season_performance" && metadata.current_season_games_played > 0 &&
          !value.items.some(item => item.season === metadata.nfl_season && item.period === "REGULAR_SEASON")) fail("CURRENT_REGULAR_SEASON_SAMPLE_MISSING");
      }
      const controls = task.baseline_controls as { top_10?: unknown; external_controls?: unknown } | undefined;
      if (requirement.name === "locked_control_comparisons") {
        const expected = controlNames(controls?.top_10);
        if (!expected.length || !expected.every(name => value.compared_controls?.includes(name))) fail("LOCKED_CONTROL_COVERAGE_MISSING");
      }
      if (requirement.name === "outside_control_comparisons") {
        const expected = controlNames(controls?.external_controls);
        if (!expected.some(name => value.compared_controls?.includes(name))) fail("NEAREST_OUTSIDE_CONTROL_MISSING");
      }
    }
  }
  const missing = [...new Set([...(Array.isArray(evidence.missing_evidence) ? evidence.missing_evidence : []), ...errors])];
  return {
    ...evidence,
    audit_type: "FULL_AUDIT",
    ...(context.status === "RESOLVED" ? context.metadata : {
      nfl_season: null, season_phase: null, evidence_season: null, sample_size_context: null,
      current_season_games_available: null, current_season_games_played: null, prior_season_used_as_primary_baseline: null
    }),
    minimum_evidence_met: missing.length === 0,
    missing_evidence: missing
  };
}

import fs from "node:fs";
import { loadState, saveState } from "./state.js";
import { getNextTask } from "./state-machine.js";
import { CodexResearchAdapter } from "./codex-research.js";
import { CodexAuditAdapter } from "./codex-adapter.js";
import { parseAuditJson } from "./audit-parser.js";
import { validateAudit } from "./audit-validator.js";
import { saveAuditRecord, queueReaudit } from "./persistence.js";
import { createCheckpoint } from "./checkpoint.js";

const MAX_REVISIONS = Number(process.env.GRIDIRON_MAX_REVISIONS ?? "3");

export async function executeNext(): Promise<Record<string, unknown>> {
  const state = loadState();
  const task = getNextTask(state);
  const locks = JSON.parse(fs.readFileSync("state/locks.json", "utf8"));

  const research = new CodexResearchAdapter();
  const evidence = await research.gather(task);

  if (!evidence.minimum_evidence_met) {
    const record = {
      audit_id: `${String((task as any).task_id ?? "task")}_INSUFFICIENT_${Date.now()}`,
      audit_type: taskTypeToAuditType(String((task as any).type ?? "")),
      status: "INSUFFICIENT_EVIDENCE",
      player_id: "N/A",
      position: String((task as any).position ?? state.current_position),
      confidence: "LOW",
      methodology_version: state.methodology_version,
      created_at: new Date().toISOString(),
      missing_evidence: evidence.missing_evidence,
      sources: evidence.sources
    };
    saveAuditRecord(record as any, renderMarkdown(record));
    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "INSUFFICIENT_EVIDENCE",
      task,
      created_at: new Date().toISOString()
    });
    return record;
  }

  const analyst = new CodexAuditAdapter();
  let feedback: string[] = [];
  let parsed: any = null;
  let validation: any = null;
  let responseText = "";

  for (let attempt = 1; attempt <= MAX_REVISIONS; attempt++) {
    const result = await analyst.runAudit({
      task,
      evidence,
      state: state as any,
      locks,
      revision_feedback: feedback
    });

    responseText = result.text;
    parsed = parseAuditJson(result.text);
    validation = validateAudit(parsed);

    if (validation.valid) break;
    feedback = validation.errors;
  }

  if (!validation?.valid) {
    parsed.status = "FLAGGED";
    parsed.major_flags = [...new Set([...(parsed.major_flags ?? []), "RE-AUDIT REQUIRED"])];
    saveAuditRecord(parsed, responseText || renderMarkdown(parsed));
    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "VALIDATION_FAILED_AFTER_3_ATTEMPTS",
      audit_id: parsed.audit_id,
      task,
      created_at: new Date().toISOString()
    });
    return parsed;
  }

  parsed.major_flags = [...new Set([...(parsed.major_flags ?? []), ...validation.flags])];
  parsed.status = validation.auto_approve ? "APPROVED" : (parsed.major_flags.length ? "FLAGGED" : "VALIDATED");

  saveAuditRecord(parsed, responseText);

  if (parsed.status === "APPROVED") {
    const taskId = String((task as any).task_id ?? "");
    if (taskId && !state.completed_tasks.includes(taskId)) {
      state.completed_tasks.push(taskId);
    }
    createCheckpoint(state, taskId || "approved");
    saveState(state);
  } else if (parsed.status === "FLAGGED") {
    queueReaudit({
      severity: "REVIEW",
      reason: parsed.major_flags,
      audit_id: parsed.audit_id,
      task,
      created_at: new Date().toISOString()
    });
  }

  return parsed;
}

function taskTypeToAuditType(type: string): string {
  if (type === "pair_audit") return "FULL_AUDIT";
  if (type === "membership_reopen") return "TOP10_REAUDIT";
  return "FULL_AUDIT";
}

function renderMarkdown(record: Record<string, unknown>): string {
  return `# ${record.audit_id}\n\nStatus: ${record.status}\n\n\`\`\`json\n${JSON.stringify(record, null, 2)}\n\`\`\``;
}

import fs from "node:fs";
import path from "node:path";
import type { ExportRequest, ExportRecord } from "./export-types.js";

function loadRegistry(): any[] {
  const file = path.resolve("data/players/registry.json");
  return JSON.parse(fs.readFileSync(file, "utf8")).players ?? [];
}

function loadCurrentCard(playerId: string): any | null {
  const file = path.resolve("data/players", playerId, "current.json");
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function loadAudit(position: string | null, auditId: string | null): any | null {
  if (!position || !auditId) return null;
  const file = path.resolve("audits/league", position, `${auditId}.json`);
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

export function collectExportRecords(request: ExportRequest): ExportRecord[] {
  const players = loadRegistry();

  const filtered = players.filter(player => {
    if (request.scope === "PLAYER") return player.player_id === request.player_id;
    if (request.scope === "POSITION") return player.position === request.position;
    if (request.scope === "TEAM") {
      if (player.team?.toUpperCase() !== request.team?.toUpperCase()) return false;
      if (request.position && player.position !== request.position) return false;
      return true;
    }
    return true;
  });

  const records: ExportRecord[] = [];

  for (const player of filtered) {
    const current = loadCurrentCard(player.player_id);

    if (!current) {
      if (!request.include_nonapproved) continue;
      records.push({
        player_id: player.player_id,
        player: player.full_name,
        team: player.team ?? null,
        position: player.position ?? null,
        ovr: null,
        ratings: {},
        audit_id: null,
        methodology_version: null,
        status: "NO_APPROVED_CURRENT_CARD",
        flags: []
      });
      continue;
    }

    const audit = loadAudit(current.position ?? player.position, current.current_audit_id ?? null);

    records.push({
      player_id: player.player_id,
      player: player.full_name,
      team: player.team ?? null,
      position: current.position ?? player.position ?? null,
      ovr: current.ovr ?? null,
      ratings: current.ratings ?? {},
      audit_id: current.current_audit_id ?? null,
      methodology_version: current.methodology_version ?? null,
      confidence: audit?.confidence ?? null,
      status: audit?.status ?? "APPROVED",
      archetype: audit?.archetype ?? audit?.player_identity ?? null,
      audit_date: audit?.created_at ?? current.approved_at ?? null,
      flags: audit?.major_flags ?? []
    });
  }

  return records;
}

import { collectExportRecords } from "./export-collector.js";
import { writeExport } from "./export-writer.js";
import { resolvePlayer } from "./player-resolver.js";
import type { ExportMode, ExportRequest } from "./export-types.js";

export function exportPlayer(query: string, mode: ExportMode) {
  const resolved = resolvePlayer(query);
  if (resolved.status !== "RESOLVED" || !resolved.player) return resolved;

  const request: ExportRequest = {
    scope: "PLAYER",
    mode,
    player_id: resolved.player.player_id
  };
  const records = collectExportRecords(request);
  return {
    status: "OK",
    records: records.length,
    files: writeExport(records, mode, resolved.player.full_name)
  };
}

export function exportPosition(position: string, mode: ExportMode) {
  const request: ExportRequest = {
    scope: "POSITION",
    mode,
    position: position.toUpperCase()
  };
  const records = collectExportRecords(request);
  return {
    status: "OK",
    records: records.length,
    files: writeExport(records, mode, `POSITION_${position.toUpperCase()}`)
  };
}

export function exportTeam(team: string, mode: ExportMode, position?: string) {
  const request: ExportRequest = {
    scope: "TEAM",
    mode,
    team: team.toUpperCase(),
    position: position?.toUpperCase()
  };
  const records = collectExportRecords(request);
  return {
    status: "OK",
    records: records.length,
    files: writeExport(
      records,
      mode,
      `TEAM_${team.toUpperCase()}${position ? "_" + position.toUpperCase() : ""}`
    )
  };
}

export function exportFullRoster(mode: ExportMode) {
  const request: ExportRequest = {
    scope: "FULL_ROSTER",
    mode
  };
  const records = collectExportRecords(request);
  return {
    status: "OK",
    records: records.length,
    files: writeExport(records, mode, "FULL_ROSTER")
  };
}

