import { resolvePlayer, findTeamPlayers } from "./player-resolver.js";
import type { Intent } from "./router.js";

export function resolveIntent(intent: Intent): Record<string, unknown> {
  if (intent.type === "FULL_PLAYER_AUDIT" ||
      intent.type === "RATINGS_ONLY" ||
      intent.type === "QUICK_RECHECK") {
    const resolution = resolvePlayer(intent.query);

    if (resolution.status === "NOT_FOUND") {
      return {
        status: "NEEDS_ROSTER_REFRESH",
        reason: "PLAYER_NOT_FOUND",
        query: intent.query
      };
    }

    if (resolution.status === "AMBIGUOUS") {
      return {
        status: "AMBIGUOUS",
        query: intent.query,
        candidates: resolution.candidates
      };
    }

    return {
      status: "RESOLVED",
      intent: intent.type,
      player: resolution.player
    };
  }

  return { status: "PASS_THROUGH", intent };
}

export function resolveTeamQuery(team: string, position?: string): Record<string, unknown> {
  const players = findTeamPlayers(team, position);
  return {
    status: players.length ? "RESOLVED" : "NEEDS_ROSTER_REFRESH",
    team: team.toUpperCase(),
    position: position?.toUpperCase() ?? null,
    players
  };
}

export function assertTop10MutationAllowed(
  baselineStatus: string,
  intent: string
): void {
  if (baselineStatus === "LOCKED" && intent !== "TOP10_REAUDIT") {
    throw new Error(
      "LOCK VIOLATION: Locked Top 10 baseline may only be changed by explicit TOP10_REAUDIT."
    );
  }
}

import { parse } from "csv-parse/sync";
import type { ExternalPlayerRecord, RosterSource } from "./roster-source.js";
import { mapToMaddenBucket } from "./position-mapper.js";

interface NflverseRow {
  season?: string;
  team?: string;
  position?: string;
  depth_chart_position?: string;
  jersey_number?: string;
  status?: string;
  full_name?: string;
  first_name?: string;
  last_name?: string;
  birth_date?: string;
  height?: string;
  weight?: string;
  college?: string;
  gsis_id?: string;
  espn_id?: string;
  pff_id?: string;
  pfr_id?: string;
  years_exp?: string;
  football_name?: string;
}

export interface NflversePlayerRecord extends ExternalPlayerRecord {
  gsis_id?: string | null;
  espn_id?: string | null;
  pff_id?: string | null;
  pfr_id?: string | null;
  depth_chart_position?: string | null;
  source_position?: string | null;
  exact_position?: string | null;
  requires_role_resolution?: boolean;
  role_resolution_reason?: string | null;
  jersey_number?: number | null;
  roster_status?: string | null;
  birth_date?: string | null;
  height?: number | null;
  weight?: number | null;
  college?: string | null;
  years_exp?: number | null;
}

export class NflverseRosterSource implements RosterSource {
  constructor(private readonly season = 2026) {}

  async fetchAllPlayers(): Promise<NflversePlayerRecord[]> {
    const url =
      `https://github.com/nflverse/nflverse-data/releases/download/rosters/roster_${this.season}.csv`;

    const response = await fetch(url, {
      headers: {
        "User-Agent": "Gridiron-Standard/1.0"
      }
    });

    if (!response.ok) {
      throw new Error(
        `nflverse roster download failed: ${response.status} ${response.statusText}`
      );
    }

    const csv = await response.text();
    const rows = parse(csv, {
      columns: true,
      skip_empty_lines: true,
      relax_column_count: true
    }) as NflverseRow[];

    return rows
      .filter(row => row.full_name && row.team)
      .map(row => this.toRecord(row));
  }

  private toRecord(row: NflverseRow): NflversePlayerRecord {
    const mapped = mapToMaddenBucket(
      row.position ?? null,
      row.depth_chart_position ?? null
    );

    const aliases = new Set<string>();
    if (row.football_name && row.football_name !== row.full_name) {
      aliases.add(row.football_name);
    }

    const sourceId =
      row.gsis_id ||
      (row.pfr_id ? `pfr_${row.pfr_id}` : "") ||
      (row.espn_id ? `espn_${row.espn_id}` : "") ||
      undefined;

    return {
      source_id: sourceId,
      full_name: row.full_name!,
      team: row.team ?? null,
      position: mapped.exact_position,
      aliases: [...aliases],

      gsis_id: row.gsis_id || null,
      espn_id: row.espn_id || null,
      pff_id: row.pff_id || null,
      pfr_id: row.pfr_id || null,

      depth_chart_position: row.depth_chart_position || null,
      source_position: row.position || null,
      exact_position: mapped.exact_position,
      requires_role_resolution: mapped.requires_role_resolution,
      role_resolution_reason: mapped.reason ?? null,

      jersey_number: toNumber(row.jersey_number),
      roster_status: row.status || null,
      birth_date: row.birth_date || null,
      height: toNumber(row.height),
      weight: toNumber(row.weight),
      college: row.college || null,
      years_exp: toNumber(row.years_exp)
    };
  }
}

function toNumber(value?: string): number | null {
  if (!value?.trim()) return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

import fs from "node:fs";
import path from "node:path";
import type { ParsedAudit } from "./audit-parser.js";

function safe(value: string): string {
  return value.replace(/[^a-zA-Z0-9._-]+/g, "_");
}

export function saveAuditRecord(audit: ParsedAudit, markdown: string): { json: string; md: string } {
  const pos = safe(audit.position);
  const dir = path.resolve("audits/league", pos);
  fs.mkdirSync(dir, { recursive: true });

  const id = safe(audit.audit_id);
  const jsonPath = path.join(dir, `${id}.json`);
  const mdPath = path.join(dir, `${id}.md`);

  // Immutable history: never overwrite an existing audit.
  if (fs.existsSync(jsonPath) || fs.existsSync(mdPath)) {
    throw new Error(`Immutable audit already exists: ${audit.audit_id}`);
  }

  fs.writeFileSync(jsonPath, JSON.stringify(audit, null, 2) + "\n");
  fs.writeFileSync(mdPath, markdown.trim() + "\n");
  return { json: jsonPath, md: mdPath };
}

export function queueReaudit(item: Record<string, unknown>): void {
  const statePath = path.resolve("state/project-state.json");
  const state = JSON.parse(fs.readFileSync(statePath, "utf8"));
  state.pending_reaudit_queue ??= [];
  state.pending_reaudit_queue.push(item);
  fs.writeFileSync(statePath, JSON.stringify(state, null, 2) + "\n");
}

import fs from "node:fs";
import path from "node:path";
import type { PlayerIdentity } from "./player-resolver.js";

export interface PlayerAuditTask {
  task_id: string;
  type: "player_full_audit";
  audit_type: "FULL_AUDIT";
  player_id: string;
  player_name: string;
  team: string | null;
  position: string;
  locked_baseline_file: string;
  current_audit_id: string | null;
}

export function buildPlayerAuditTask(player: PlayerIdentity): PlayerAuditTask {
  if (!player.position) {
    throw new Error(
      `PLAYER_POSITION_UNRESOLVED: ${player.full_name} requires exact Madden position resolution before Full Audit.`
    );
  }

  const baselinePath = path.resolve(`data/baselines/${player.position}.json`);
  if (!fs.existsSync(baselinePath)) {
    throw new Error(
      `BASELINE_NOT_AVAILABLE: ${player.position} does not yet have a positional baseline file.`
    );
  }

  const baseline = JSON.parse(fs.readFileSync(baselinePath, "utf8"));
  if (baseline.status !== "LOCKED") {
    throw new Error(
      `BASELINE_NOT_LOCKED: ${player.position} must have a locked Top 10 before one-off player audits can use it as authoritative calibration.`
    );
  }

  const safe = player.player_id.replace(/[^a-zA-Z0-9._-]+/g, "_");
  return {
    task_id: `PLAYER_${safe}_${Date.now()}`,
    type: "player_full_audit",
    audit_type: "FULL_AUDIT",
    player_id: player.player_id,
    player_name: player.full_name,
    team: player.team ?? null,
    position: player.position,
    locked_baseline_file: `data/baselines/${player.position}.json`,
    current_audit_id: player.current_audit_id ?? null
  };
}

import fs from "node:fs";
import { buildPlayerAuditTask } from "./player-audit-task.js";
import { loadBaselineControls } from "./baseline-controls.js";
import { CodexResearchAdapter } from "./codex-research.js";
import { CodexAuditAdapter } from "./codex-adapter.js";
import { parseAuditJson } from "./audit-parser.js";
import { validateAudit } from "./audit-validator.js";
import { saveAuditRecord, queueReaudit } from "./persistence.js";
import { linkApprovedAuditToPlayer, getCurrentApprovedCard } from "./player-history.js";
import type { PlayerIdentity } from "./player-resolver.js";
import { applyFullAuditEvidenceGate } from "./evidence-gate.js";

const MAX_REVISIONS = Number(process.env.GRIDIRON_MAX_REVISIONS ?? "3");

export async function executePlayerAudit(player: PlayerIdentity): Promise<Record<string, unknown>> {
  const task = buildPlayerAuditTask(player);
  const controls = loadBaselineControls(task.position);
  const locks = JSON.parse(fs.readFileSync("state/locks.json", "utf8"));
  const state = JSON.parse(fs.readFileSync("state/project-state.json", "utf8"));
  const previousCard = getCurrentApprovedCard(player.player_id);

  const research = new CodexResearchAdapter();
  const researchTask = {
    ...task,
    baseline_controls: {
      top_10: controls.top_10,
      first_out: controls.first_out,
      external_controls: controls.external_controls
    },
    previous_card: previousCard
  };
  const evidence = applyFullAuditEvidenceGate(
    await research.gather(researchTask), researchTask, new Date().toISOString()
  );

  if (!evidence.minimum_evidence_met) {
    const record = {
      audit_id: `${task.task_id}_INSUFFICIENT`,
      audit_type: "FULL_AUDIT",
      status: "INSUFFICIENT_EVIDENCE",
      player_id: player.player_id,
      position: task.position,
      confidence: "LOW",
      methodology_version: state.methodology_version,
      created_at: new Date().toISOString(),
      missing_evidence: evidence.missing_evidence,
      sources: evidence.sources
    };

    saveAuditRecord(record as any, renderMarkdown(record));
    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "INSUFFICIENT_EVIDENCE",
      player_id: player.player_id,
      audit_id: record.audit_id,
      created_at: new Date().toISOString()
    });
    return record;
  }

  const analyst = new CodexAuditAdapter();
  let feedback: string[] = [];
  let parsed: any = null;
  let validation: any = null;
  let responseText = "";

  for (let attempt = 1; attempt <= MAX_REVISIONS; attempt++) {
    const result = await analyst.runAudit({
      task: {
        ...task,
        requirements: {
          use_locked_top10_as_primary_reference: true,
          use_nearest_external_controls: true,
          why_not_higher_required: true,
          why_not_lower_required: true,
          player_identity_required: true,
          challenger_flag_required_if_close: true,
          may_not_mutate_locked_top10: true
        },
        baseline_controls: controls,
        previous_card: previousCard
      },
      evidence,
      state,
      locks,
      revision_feedback: feedback
    });

    responseText = result.text;
    parsed = parseAuditJson(result.text);

    // Canonical identity fields are application-controlled.
    parsed.player_id = player.player_id;
    parsed.position = task.position;
    parsed.audit_type = "FULL_AUDIT";
    parsed.methodology_version = state.methodology_version;
    parsed.created_at ??= new Date().toISOString();

    validation = validateAudit(parsed);

    // Structural Gridiron requirements for one-off player audits.
    if (!Array.isArray(parsed.nearest_controls) || parsed.nearest_controls.length === 0) {
      validation.errors.push("Missing nearest_controls.");
      validation.valid = false;
    }
    if (!parsed.player_identity) {
      validation.errors.push("Missing player_identity.");
      validation.valid = false;
    }
    if (!parsed.why_not_higher) {
      validation.errors.push("Missing why_not_higher.");
      validation.valid = false;
    }
    if (!parsed.why_not_lower) {
      validation.errors.push("Missing why_not_lower.");
      validation.valid = false;
    }

    if (validation.valid) break;
    feedback = validation.errors;
  }

  if (!validation?.valid) {
    parsed.status = "FLAGGED";
    parsed.major_flags = [...new Set([...(parsed.major_flags ?? []), "RE-AUDIT REQUIRED"])];
    saveAuditRecord(parsed, responseText || renderMarkdown(parsed));
    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "VALIDATION_FAILED_AFTER_3_ATTEMPTS",
      player_id: player.player_id,
      audit_id: parsed.audit_id,
      created_at: new Date().toISOString()
    });
    return parsed;
  }

  parsed.major_flags = [...new Set([...(parsed.major_flags ?? []), ...validation.flags])];
  parsed.status = validation.auto_approve ? "APPROVED" : (parsed.major_flags.length ? "FLAGGED" : "VALIDATED");

  saveAuditRecord(parsed, responseText);

  if (parsed.status === "APPROVED") {
    linkApprovedAuditToPlayer(parsed);
  } else if (parsed.status === "FLAGGED") {
    queueReaudit({
      severity: parsed.challenger_flag ? "RE-AUDIT REQUIRED" : "REVIEW",
      reason: parsed.major_flags,
      player_id: player.player_id,
      audit_id: parsed.audit_id,
      challenger_flag: parsed.challenger_flag ?? false,
      created_at: new Date().toISOString()
    });
  }

  return parsed;
}

function renderMarkdown(record: Record<string, unknown>): string {
  return `# ${record.audit_id}\n\nStatus: ${record.status}\n\n\`\`\`json\n${JSON.stringify(record, null, 2)}\n\`\`\``;
}

import fs from "node:fs";
import path from "node:path";
