export interface ApprovedCurrentCard {
  player_id: string;
  current_audit_id: string;
  position: string;
  ovr: number | null;
  ratings: Record<string, number>;
  approved_at: string;
  methodology_version: string;
}

export function linkApprovedAuditToPlayer(audit: ParsedAudit): void {
  if (!audit.player_id) throw new Error("Approved audit missing player_id.");

  const registryPath = path.resolve("data/players/registry.json");
  const registry = JSON.parse(fs.readFileSync(registryPath, "utf8"));
  const player = registry.players.find((p: any) => p.player_id === audit.player_id);

  if (!player) throw new Error(`Unknown player_id: ${audit.player_id}`);

  player.audit_history ??= [];
  if (!player.audit_history.includes(audit.audit_id)) {
    player.audit_history.push(audit.audit_id);
  }
  player.current_audit_id = audit.audit_id;

  fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2) + "\n");

  const dir = path.resolve("data/players", audit.player_id);
  fs.mkdirSync(dir, { recursive: true });

  const snapshot: ApprovedCurrentCard = {
    player_id: audit.player_id,
    current_audit_id: audit.audit_id,
    position: audit.position,
    ovr: audit.ovr_after ?? null,
    ratings: audit.ratings ?? {},
    approved_at: audit.created_at,
    methodology_version: audit.methodology_version
  };

  fs.writeFileSync(
    path.join(dir, "current.json"),
    JSON.stringify(snapshot, null, 2) + "\n"
  );
}

export function getCurrentApprovedCard(playerId: string): ApprovedCurrentCard | null {
  const file = path.resolve("data/players", playerId, "current.json");
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

import fs from "node:fs";
import path from "node:path";

export interface PlayerIdentity {
  player_id: string;
  full_name: string;
  aliases: string[];
  team: string | null;
  position: string | null;
  historical_positions: string[];
  current_audit_id: string | null;
  audit_history: string[];
}

export interface Resolution {
  status: "RESOLVED" | "AMBIGUOUS" | "NOT_FOUND";
  player?: PlayerIdentity;
  candidates?: PlayerIdentity[];
  query: string;
}

function normalize(value: string): string {
  return value
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function loadRegistry(): PlayerIdentity[] {
  const file = path.resolve("data/players/registry.json");
  const data = JSON.parse(fs.readFileSync(file, "utf8"));
  return data.players as PlayerIdentity[];
}

export function resolvePlayer(
  query: string,
  team?: string,
  position?: string
): Resolution {
  const q = normalize(query);
  const players = loadRegistry();

  const scored = players
    .map(player => {
      const names = [
        player.full_name,
        ...(player.aliases ?? [])
      ].map(normalize);

      let score = 0;
      if (names.includes(q)) score += 100;
      if (normalize(player.full_name).endsWith(" " + q)) score += 70;
      if (normalize(player.full_name).startsWith(q + " ")) score += 50;
      if (normalize(player.full_name).includes(q)) score += 30;

      if (team && player.team?.toUpperCase() === team.toUpperCase()) score += 20;
      if (position && player.position === position.toUpperCase()) score += 20;

      return { player, score };
    })
    .filter(x => x.score > 0)
    .sort((a,b) => b.score - a.score);

  if (!scored.length) return { status: "NOT_FOUND", query };

  const top = scored[0].score;
  const tied = scored.filter(x => x.score === top).map(x => x.player);

  if (tied.length > 1) {
    return { status: "AMBIGUOUS", query, candidates: tied };
  }

  return { status: "RESOLVED", query, player: tied[0] };
}

export function findTeamPlayers(team: string, position?: string): PlayerIdentity[] {
  return loadRegistry().filter(p =>
    p.team?.toUpperCase() === team.toUpperCase() &&
    (!position || p.position === position.toUpperCase())
  );
}

export interface PositionMapping {
  exact_position: string | null;
  source_position: string | null;
  depth_chart_position: string | null;
  requires_role_resolution: boolean;
  reason?: string;
}

const EXACT = new Set([
  "QB","RB","WR","TE","LT","LG","C","RG","RT","DT","CB","FS","SS","K","P"
]);

export function mapToMaddenBucket(
  position?: string | null,
  depthChartPosition?: string | null
): PositionMapping {
  const p = (position ?? "").toUpperCase().trim() || null;
  const d = (depthChartPosition ?? "").toUpperCase().trim() || null;

  if (d && EXACT.has(d)) {
    return {
      exact_position: d,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: false
    };
  }

  if (p && EXACT.has(p)) {
    return {
      exact_position: p,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: false
    };
  }

  // Madden-specific buckets that cannot safely be inferred from generic NFL labels.
  if (["OLB","LB","EDGE","DE"].includes(d ?? "") ||
      ["OLB","LB","EDGE","DE"].includes(p ?? "")) {
    return {
      exact_position: null,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: true,
      reason: "Must resolve exact REDGE/LEDGE/MIKE/WILL/SAM role from current usage and depth-chart evidence."
    };
  }

  if (["ILB","MLB"].includes(d ?? "") || ["ILB","MLB"].includes(p ?? "")) {
    return {
      exact_position: null,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: true,
      reason: "Interior linebacker label is insufficient to distinguish MIKE/WILL/SAM under Gridiron Standard."
    };
  }

  if (["OL","T","G"].includes(d ?? "") || ["OL","T","G"].includes(p ?? "")) {
    return {
      exact_position: null,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: true,
      reason: "Generic offensive-line designation does not identify exact LT/LG/C/RG/RT bucket."
    };
  }

  if (["S","DB"].includes(d ?? "") || ["S","DB"].includes(p ?? "")) {
    return {
      exact_position: null,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: true,
      reason: "Generic safety/defensive-back designation does not identify exact FS/SS bucket."
    };
  }

  return {
    exact_position: null,
    source_position: p,
    depth_chart_position: d,
    requires_role_resolution: true,
    reason: "Source position cannot be mapped safely to an exact Gridiron Standard bucket."
  };
}

import fs from "node:fs";
import path from "node:path";

type Check = { name: string; ok: boolean; detail?: string };

function exists(rel: string): boolean {
  return fs.existsSync(path.resolve(rel));
}

function readJson(rel: string): any {
  return JSON.parse(fs.readFileSync(path.resolve(rel), "utf8"));
}

const checks: Check[] = [];

for (const rel of [
  "AGENTS.md",
  "state/project-state.json",
  "state/locks.json",
  "data/players/registry.json",
  "config/output-policy.json",
  "config/team-branding.json",
  "config/madden-entry-order.json"
]) {
  checks.push({
    name: `file:${rel}`,
    ok: exists(rel),
    detail: exists(rel) ? undefined : "missing"
  });
}

try {
  const state = readJson("state/project-state.json");
  checks.push({
    name: "architecture_version",
    ok: state.architecture_version === "1.0.0",
    detail: String(state.architecture_version)
  });
  checks.push({
    name: "review_mode",
    ok: state.review_mode === "REVIEW_MAJOR",
    detail: String(state.review_mode)
  });
} catch (error) {
  checks.push({
    name: "project_state_parse",
    ok: false,
    detail: error instanceof Error ? error.message : String(error)
  });
}

try {
  const policy = readJson("config/output-policy.json");
  checks.push({
    name: "card_photo_disabled",
    ok: policy.graphic_input_card?.include_player_photo === false
  });
  checks.push({
    name: "card_requires_explicit_request",
    ok: policy.graphic_input_card?.generate_only_on_explicit_request === true
  });
} catch (error) {
  checks.push({
    name: "output_policy_parse",
    ok: false,
    detail: error instanceof Error ? error.message : String(error)
  });
}

try {
  const order = readJson("config/madden-entry-order.json");
  checks.push({
    name: "madden_order_registry_present",
    ok: Boolean(order.positions)
  });
  checks.push({
    name: "madden_order_verified",
    ok: order.verified === true,
    detail: order.verified === true
      ? "verified"
      : "NOT VERIFIED: deployment may serve ratings, but production graphic card generation should remain gated."
  });
} catch (error) {
  checks.push({
    name: "madden_order_parse",
    ok: false,
    detail: error instanceof Error ? error.message : String(error)
  });
}

const failed = checks.filter(x => !x.ok);
console.log(JSON.stringify({
  status: failed.length ? "FAIL" : "PASS",
  checks
}, null, 2));

if (failed.some(x => x.name !== "madden_order_verified")) {
  process.exitCode = 1;
}

import fs from "node:fs";
import { CodexResearchAdapter } from "./codex-research.js";
import { CodexAuditAdapter } from "./codex-adapter.js";
import { parseAuditJson } from "./audit-parser.js";
import { validateAudit } from "./audit-validator.js";
import { saveAuditRecord, queueReaudit } from "./persistence.js";
import { getCurrentApprovedCard, linkApprovedAuditToPlayer } from "./player-history.js";
import { loadBaselineControls } from "./baseline-controls.js";
import type { PlayerIdentity } from "./player-resolver.js";

const MAX_REVISIONS = Number(process.env.GRIDIRON_MAX_REVISIONS ?? "3");

export async function executeQuickRecheck(
  player: PlayerIdentity
): Promise<Record<string, unknown>> {
  const current = getCurrentApprovedCard(player.player_id);

  if (!current) {
    return {
      status: "FULL_AUDIT_REQUIRED",
      player_id: player.player_id,
      player: player.full_name,
      reason: "Quick Recheck requires an existing approved current card."
    };
  }

  const position = String(current.position ?? player.position ?? "");
  if (!position) {
    return {
      status: "FULL_AUDIT_REQUIRED",
      player_id: player.player_id,
      player: player.full_name,
      reason: "Exact Madden position is unresolved."
    };
  }

  const controls = loadBaselineControls(position);
  const locks = JSON.parse(fs.readFileSync("state/locks.json", "utf8"));
  const state = JSON.parse(fs.readFileSync("state/project-state.json", "utf8"));

  const task = {
    task_id: `QUICK_${player.player_id}_${Date.now()}`,
    type: "quick_recheck",
    audit_type: "QUICK_RECHECK",
    player_id: player.player_id,
    player_name: player.full_name,
    team: player.team ?? null,
    position,
    previous_card: current,
    baseline_controls: {
      top_10: controls.top_10,
      first_out: controls.first_out,
      external_controls: controls.external_controls
    },
    constraints: {
      max_ovr_change: 1,
      may_add_or_remove_95_plus: false,
      may_modify_locked_top10: false,
      escalate_if_material_architecture_change: true,
      escalate_if_top10_challenger: true
    }
  };

  const research = new CodexResearchAdapter();
  const evidence = await research.gather(task);

  if (!evidence.minimum_evidence_met) {
    const record = {
      audit_id: `${task.task_id}_INSUFFICIENT`,
      audit_type: "QUICK_RECHECK",
      status: "INSUFFICIENT_EVIDENCE",
      player_id: player.player_id,
      position,
      confidence: "LOW",
      methodology_version: state.methodology_version,
      created_at: new Date().toISOString(),
      missing_evidence: evidence.missing_evidence,
      sources: evidence.sources
    };

    saveAuditRecord(record as any, renderMarkdown(record));
    queueReaudit({
      severity: "REVIEW",
      reason: "QUICK_RECHECK_INSUFFICIENT_EVIDENCE",
      player_id: player.player_id,
      audit_id: record.audit_id,
      created_at: new Date().toISOString()
    });
    return record;
  }

  const analyst = new CodexAuditAdapter();
  let feedback: string[] = [];
  let parsed: any = null;
  let validation: any = null;
  let responseText = "";

  for (let attempt = 1; attempt <= MAX_REVISIONS; attempt++) {
    const result = await analyst.runAudit({
      task,
      evidence,
      state,
      locks,
      revision_feedback: feedback
    });

    responseText = result.text;
    parsed = parseAuditJson(result.text);

    parsed.player_id = player.player_id;
    parsed.position = position;
    parsed.audit_type = "QUICK_RECHECK";
    parsed.methodology_version = state.methodology_version;
    parsed.created_at ??= new Date().toISOString();
    parsed.ovr_before = Number(current.ovr);

    validation = validateAudit(parsed);

    const errors = validation.errors as string[];

    if (typeof parsed.ovr_after !== "number") {
      errors.push("Quick Recheck missing numeric ovr_after.");
    } else if (Math.abs(parsed.ovr_after - Number(current.ovr)) > 1) {
      errors.push("Quick Recheck exceeds 1-point OVR limit.");
    }

    if (parsed.added_95_plus || parsed.removed_95_plus) {
      errors.push("Quick Recheck cannot add or remove 95+ traits.");
    }

    if (parsed.challenger_flag) {
      errors.push("Top 10 challenger requires Full Audit / positional review.");
    }

    if (parsed.material_attribute_redistribution === true) {
      errors.push("Material attribute redistribution requires Full Audit.");
    }

    validation.valid = errors.length === 0;
    if (validation.valid) break;
    feedback = errors;
  }

  if (!validation?.valid) {
    const escalation = {
      status: "FULL_AUDIT_REQUIRED",
      player_id: player.player_id,
      player: player.full_name,
      reason: "Quick Recheck exceeded allowed scope or failed validation.",
      validation_errors: validation?.errors ?? [],
      previous_audit_id: current.current_audit_id ?? null
    };

    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "QUICK_RECHECK_ESCALATED_TO_FULL_AUDIT",
      player_id: player.player_id,
      detail: escalation,
      created_at: new Date().toISOString()
    });

    return escalation;
  }

  parsed.major_flags = [...new Set([
    ...(parsed.major_flags ?? []),
    ...validation.flags
  ])];

  parsed.status = validation.auto_approve
    ? "APPROVED"
    : (parsed.major_flags.length ? "FLAGGED" : "VALIDATED");

  saveAuditRecord(parsed, responseText);

  if (parsed.status === "APPROVED") {
    linkApprovedAuditToPlayer(parsed);
  } else if (parsed.status === "FLAGGED") {
    queueReaudit({
      severity: "REVIEW",
      reason: parsed.major_flags,
      player_id: player.player_id,
      audit_id: parsed.audit_id,
      created_at: new Date().toISOString()
    });
  }

  return parsed;
}

function renderMarkdown(record: Record<string, unknown>): string {
  return `# ${record.audit_id}\n\nStatus: ${record.status}\n\n\`\`\`json\n${JSON.stringify(record, null, 2)}\n\`\`\``;
}

