import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { route } from "../src/router.js";
import { majorFlags, mayAutoApprove } from "../src/validator.js";
import { mapToMaddenBucket } from "../src/position-mapper.js";

function test(name: string, fn: () => void): void {
  try {
    fn();
    console.log(`PASS ${name}`);
  } catch (error) {
    console.error(`FAIL ${name}`);
    throw error;
  }
}

test("route continue alias", () => {
  assert.deepEqual(route("go"), { type: "CONTINUE" });
});

test("route card command", () => {
  assert.deepEqual(route("card Jalen Hurts"), {
    type: "CARD_PLAYER",
    query: "Jalen Hurts"
  });
});

test("quick recheck 2-point change flags", () => {
  const flags = majorFlags({
    audit_type: "QUICK_RECHECK",
    confidence: "HIGH",
    ovr_before: 82,
    ovr_after: 84
  });
  assert(flags.includes("OVR_CHANGE_2_PLUS"));
  assert(flags.includes("QUICK_RECHECK_EXCEEDS_OVR_LIMIT"));
});

test("high-confidence clean audit auto-approves", () => {
  assert.equal(mayAutoApprove({
    audit_type: "FULL_AUDIT",
    confidence: "HIGH",
    ovr_before: 82,
    ovr_after: 83
  }), true);
});

test("generic OLB is not guessed", () => {
  const mapped = mapToMaddenBucket("OLB", "OLB");
  assert.equal(mapped.exact_position, null);
  assert.equal(mapped.requires_role_resolution, true);
});

test("LT maps exactly", () => {
  const mapped = mapToMaddenBucket("T", "LT");
  assert.equal(mapped.exact_position, "LT");
  assert.equal(mapped.requires_role_resolution, false);
});

test("output policy forbids player photo", () => {
  const policy = JSON.parse(
    fs.readFileSync(path.resolve("config/output-policy.json"), "utf8")
  );
  assert.equal(policy.graphic_input_card.include_player_photo, false);
});

test("locked baseline files exist", () => {
  for (const pos of ["QB","RB","WR","TE","LT"]) {
    assert.equal(fs.existsSync(path.resolve(`data/baselines/${pos}.json`)), true);
  }
});

import fs from "node:fs";
import { loadState, saveState } from "./state.js";
import { getNextTask } from "./state-machine.js";
import { CodexResearchAdapter } from "./codex-research.js";
import { CodexAuditAdapter } from "./codex-adapter.js";
import { parseAuditJson } from "./audit-parser.js";
import { validateAudit } from "./audit-validator.js";
import { saveAuditRecord, queueReaudit } from "./persistence.js";
import { createCheckpoint } from "./checkpoint.js";

const MAX_REVISIONS = Number(process.env.GRIDIRON_MAX_REVISIONS ?? "3");

export async function executeNext(): Promise<Record<string, unknown>> {
  const state = loadState();
  const task = getNextTask(state);
  const locks = JSON.parse(fs.readFileSync("state/locks.json", "utf8"));

  const research = new CodexResearchAdapter();
  const evidence = await research.gather(task);

  if (!evidence.minimum_evidence_met) {
    const record = {
      audit_id: `${String((task as any).task_id ?? "task")}_INSUFFICIENT_${Date.now()}`,
      audit_type: taskTypeToAuditType(String((task as any).type ?? "")),
      status: "INSUFFICIENT_EVIDENCE",
      player_id: "N/A",
      position: String((task as any).position ?? state.current_position),
      confidence: "LOW",
      methodology_version: state.methodology_version,
      created_at: new Date().toISOString(),
      missing_evidence: evidence.missing_evidence,
      sources: evidence.sources
    };
    saveAuditRecord(record as any, renderMarkdown(record));
    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "INSUFFICIENT_EVIDENCE",
      task,
      created_at: new Date().toISOString()
    });
    return record;
  }

  const analyst = new CodexAuditAdapter();
  let feedback: string[] = [];
  let parsed: any = null;
  let validation: any = null;
  let responseText = "";

  for (let attempt = 1; attempt <= MAX_REVISIONS; attempt++) {
    const result = await analyst.runAudit({
      task,
      evidence,
      state: state as any,
      locks,
      revision_feedback: feedback
    });

    responseText = result.text;
    parsed = parseAuditJson(result.text);
    validation = validateAudit(parsed);

    if (validation.valid) break;
    feedback = validation.errors;
  }

  if (!validation?.valid) {
    parsed.status = "FLAGGED";
    parsed.major_flags = [...new Set([...(parsed.major_flags ?? []), "RE-AUDIT REQUIRED"])];
    saveAuditRecord(parsed, responseText || renderMarkdown(parsed));
    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "VALIDATION_FAILED_AFTER_3_ATTEMPTS",
      audit_id: parsed.audit_id,
      task,
      created_at: new Date().toISOString()
    });
    return parsed;
  }

  parsed.major_flags = [...new Set([...(parsed.major_flags ?? []), ...validation.flags])];
  parsed.status = validation.auto_approve ? "APPROVED" : (parsed.major_flags.length ? "FLAGGED" : "VALIDATED");

  saveAuditRecord(parsed, responseText);

  if (parsed.status === "APPROVED") {
    const taskId = String((task as any).task_id ?? "");
    if (taskId && !state.completed_tasks.includes(taskId)) {
      state.completed_tasks.push(taskId);
    }
    createCheckpoint(state, taskId || "approved");
    saveState(state);
  } else if (parsed.status === "FLAGGED") {
    queueReaudit({
      severity: "REVIEW",
      reason: parsed.major_flags,
      audit_id: parsed.audit_id,
      task,
      created_at: new Date().toISOString()
    });
  }

  return parsed;
}

function taskTypeToAuditType(type: string): string {
  if (type === "pair_audit") return "FULL_AUDIT";
  if (type === "membership_reopen") return "TOP10_REAUDIT";
  return "FULL_AUDIT";
}

function renderMarkdown(record: Record<string, unknown>): string {
  return `# ${record.audit_id}\n\nStatus: ${record.status}\n\n\`\`\`json\n${JSON.stringify(record, null, 2)}\n\`\`\``;
}

import { collectExportRecords } from "./export-collector.js";
import { writeExport } from "./export-writer.js";
import { resolvePlayer } from "./player-resolver.js";
import type { ExportMode, ExportRequest } from "./export-types.js";

export function exportPlayer(query: string, mode: ExportMode) {
  const resolved = resolvePlayer(query);
  if (resolved.status !== "RESOLVED" || !resolved.player) return resolved;

  const request: ExportRequest = {
    scope: "PLAYER",
    mode,
    player_id: resolved.player.player_id
  };
  const records = collectExportRecords(request);
  return {
    status: "OK",
    records: records.length,
    files: writeExport(records, mode, resolved.player.full_name)
  };
}

export function exportPosition(position: string, mode: ExportMode) {
  const request: ExportRequest = {
    scope: "POSITION",
    mode,
    position: position.toUpperCase()
  };
  const records = collectExportRecords(request);
  return {
    status: "OK",
    records: records.length,
    files: writeExport(records, mode, `POSITION_${position.toUpperCase()}`)
  };
}

export function exportTeam(team: string, mode: ExportMode, position?: string) {
  const request: ExportRequest = {
    scope: "TEAM",
    mode,
    team: team.toUpperCase(),
    position: position?.toUpperCase()
  };
  const records = collectExportRecords(request);
  return {
    status: "OK",
    records: records.length,
    files: writeExport(
      records,
      mode,
      `TEAM_${team.toUpperCase()}${position ? "_" + position.toUpperCase() : ""}`
    )
  };
}

export function exportFullRoster(mode: ExportMode) {
  const request: ExportRequest = {
    scope: "FULL_ROSTER",
    mode
  };
  const records = collectExportRecords(request);
  return {
    status: "OK",
    records: records.length,
    files: writeExport(records, mode, "FULL_ROSTER")
  };
}

export interface EvidenceSource {
  name: string;
  url: string | null;
  published_at: string | null;
  retrieved_at: string;
  authority_tier: 1 | 2 | 3 | 4 | 5;
  claims: string[];
}

export interface EvidencePackage {
  task_id: string;
  position: string;
  researched_at: string;
  sources: EvidenceSource[];
  normalized: Record<string, unknown>;
  conflicts: Record<string, unknown>[];
  minimum_evidence_met: boolean;
  missing_evidence: string[];
}

export interface ResearchAdapter {
  gather(task: Record<string, unknown>): Promise<EvidencePackage>;
}

export type Intent =
  | { type: "CONTINUE" }
  | { type: "STATUS" }
  | { type: "FULL_PLAYER_AUDIT"; query: string }
  | { type: "RATINGS_ONLY"; query: string }
  | { type: "QUICK_RECHECK"; query: string }
  | { type: "TOP10_REAUDIT"; position: string }
  | { type: "TEAM_AUDIT"; team: string; position?: string }
  | { type: "TEAM_ROOM_LOCK"; team: string; position: string }
  | { type: "EXPORT_PLAYER"; query: string; mode: "MADDEN_ENTRY" | "AUDIT_RICH" }
  | { type: "EXPORT_POSITION"; position: string; mode: "MADDEN_ENTRY" | "AUDIT_RICH" }
  | { type: "EXPORT_TEAM"; team: string; position?: string; mode: "MADDEN_ENTRY" | "AUDIT_RICH" }
  | { type: "EXPORT_FULL"; mode: "MADDEN_ENTRY" | "AUDIT_RICH" }
  | { type: "CARD_PLAYER"; query: string }
  | { type: "UNKNOWN"; raw: string };

export function route(input: string): Intent {
  const value = input.trim();
  const lower = value.toLowerCase();

  if (["go", "continue", "next"].includes(lower)) return { type: "CONTINUE" };
  if (lower === "status") return { type: "STATUS" };

  const ratings = value.match(/^ratings?\s+(.+)$/i);
  if (ratings) return { type: "RATINGS_ONLY", query: ratings[1].trim() };

  const audit = value.match(/^audit\s+(.+)$/i);
  if (audit) return { type: "FULL_PLAYER_AUDIT", query: audit[1].trim() };

  const recheck = value.match(/^(?:recheck|quick recheck)\s+(.+)$/i);
  if (recheck) return { type: "QUICK_RECHECK", query: recheck[1].trim() };



  const inputCard = value.match(/^(?:card|input\s+card|madden\s+card)\s+(.+)$/i);
  if (inputCard) return {
    type: "CARD_PLAYER",
    query: inputCard[1].trim()
  };

  const exportFull = value.match(/^export\s+full(?:\s+roster)?\s+(madden|rich)$/i);
  if (exportFull) return {
    type: "EXPORT_FULL",
    mode: exportFull[1].toLowerCase() === "rich" ? "AUDIT_RICH" : "MADDEN_ENTRY"
  };

  const exportTeam = value.match(/^export\s+team\s+([A-Za-z]{2,4})(?:\s+(QB|RB|WR|TE|LT|LG|C|RG|RT|REDGE|LEDGE|DT|MIKE|WILL|SAM|CB|FS|SS|K|P))?\s+(madden|rich)$/i);
  if (exportTeam) return {
    type: "EXPORT_TEAM",
    team: exportTeam[1].toUpperCase(),
    position: exportTeam[2]?.toUpperCase(),
    mode: exportTeam[3].toLowerCase() === "rich" ? "AUDIT_RICH" : "MADDEN_ENTRY"
  };

  const exportPosition = value.match(/^export\s+position\s+(QB|RB|WR|TE|LT|LG|C|RG|RT|REDGE|LEDGE|DT|MIKE|WILL|SAM|CB|FS|SS|K|P)\s+(madden|rich)$/i);
  if (exportPosition) return {
    type: "EXPORT_POSITION",
    position: exportPosition[1].toUpperCase(),
    mode: exportPosition[2].toLowerCase() === "rich" ? "AUDIT_RICH" : "MADDEN_ENTRY"
  };

  const exportPlayer = value.match(/^export\s+player\s+(.+?)\s+(madden|rich)$/i);
  if (exportPlayer) return {
    type: "EXPORT_PLAYER",
    query: exportPlayer[1].trim(),
    mode: exportPlayer[2].toLowerCase() === "rich" ? "AUDIT_RICH" : "MADDEN_ENTRY"
  };

  const teamLock = value.match(/^lock\s+team\s+([A-Za-z]{2,4})\s+(QB|RB|WR|TE|LT|LG|C|RG|RT|REDGE|LEDGE|DT|MIKE|WILL|SAM|CB|FS|SS|K|P)$/i);
  if (teamLock) return {
    type: "TEAM_ROOM_LOCK",
    team: teamLock[1].toUpperCase(),
    position: teamLock[2].toUpperCase()
  };

  const teamAudit = value.match(/^audit\s+team\s+([A-Za-z]{2,4})(?:\s+(QB|RB|WR|TE|LT|LG|C|RG|RT|REDGE|LEDGE|DT|MIKE|WILL|SAM|CB|FS|SS|K|P))?$/i);
  if (teamAudit) return {
    type: "TEAM_AUDIT",
    team: teamAudit[1].toUpperCase(),
    position: teamAudit[2]?.toUpperCase()
  };

  const top10 = value.match(/^re-audit\s+(\w+)\s+top\s*10$/i);
  if (top10) return { type: "TOP10_REAUDIT", position: top10[1].toUpperCase() };

  return { type: "UNKNOWN", raw: value };
}

import { executeNext } from "./executor.js";
import { loadState } from "./state.js";

const maxSteps = Number(process.env.GRIDIRON_MAX_STEPS ?? "100");
const stopOnMajorFlag = (process.env.GRIDIRON_STOP_ON_MAJOR_FLAG ?? "true") === "true";

for (let step = 1; step <= maxSteps; step++) {
  const before = loadState();
  console.log(`[${step}/${maxSteps}] ${before.current_position} :: ${before.current_stage}`);

  try {
    const result: any = await executeNext();
    console.log(JSON.stringify({
      audit_id: result.audit_id,
      status: result.status,
      position: result.position,
      ovr_after: result.ovr_after ?? null,
      major_flags: result.major_flags ?? []
    }, null, 2));

    if (result.status === "INSUFFICIENT_EVIDENCE") {
      console.error("Stopping: required evidence unavailable.");
      process.exitCode = 3;
      break;
    }

    if (stopOnMajorFlag && result.status === "FLAGGED") {
      console.error("Stopping: major review flag requires user decision.");
      process.exitCode = 4;
      break;
    }
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
    break;
  }
}

export interface PositionMapping {
  exact_position: string | null;
  source_position: string | null;
  depth_chart_position: string | null;
  requires_role_resolution: boolean;
  reason?: string;
}

const EXACT = new Set([
  "QB","RB","WR","TE","LT","LG","C","RG","RT","DT","CB","FS","SS","K","P"
]);

export function mapToMaddenBucket(
  position?: string | null,
  depthChartPosition?: string | null
): PositionMapping {
  const p = (position ?? "").toUpperCase().trim() || null;
  const d = (depthChartPosition ?? "").toUpperCase().trim() || null;

  if (d && EXACT.has(d)) {
    return {
      exact_position: d,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: false
    };
  }

  if (p && EXACT.has(p)) {
    return {
      exact_position: p,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: false
    };
  }

  // Madden-specific buckets that cannot safely be inferred from generic NFL labels.
  if (["OLB","LB","EDGE","DE"].includes(d ?? "") ||
      ["OLB","LB","EDGE","DE"].includes(p ?? "")) {
    return {
      exact_position: null,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: true,
      reason: "Must resolve exact REDGE/LEDGE/MIKE/WILL/SAM role from current usage and depth-chart evidence."
    };
  }

  if (["ILB","MLB"].includes(d ?? "") || ["ILB","MLB"].includes(p ?? "")) {
    return {
      exact_position: null,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: true,
      reason: "Interior linebacker label is insufficient to distinguish MIKE/WILL/SAM under Gridiron Standard."
    };
  }

  if (["OL","T","G"].includes(d ?? "") || ["OL","T","G"].includes(p ?? "")) {
    return {
      exact_position: null,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: true,
      reason: "Generic offensive-line designation does not identify exact LT/LG/C/RG/RT bucket."
    };
  }

  if (["S","DB"].includes(d ?? "") || ["S","DB"].includes(p ?? "")) {
    return {
      exact_position: null,
      source_position: p,
      depth_chart_position: d,
      requires_role_resolution: true,
      reason: "Generic safety/defensive-back designation does not identify exact FS/SS bucket."
    };
  }

  return {
    exact_position: null,
    source_position: p,
    depth_chart_position: d,
    requires_role_resolution: true,
    reason: "Source position cannot be mapped safely to an exact Gridiron Standard bucket."
  };
}

import fs from "node:fs";
import path from "node:path";
import { Codex } from "@openai/codex-sdk";

export interface CodexRunInput {
  task: Record<string, unknown>;
  evidence: Record<string, unknown>;
  state: Record<string, unknown>;
  locks: Record<string, unknown>;
  revision_feedback?: string[];
}

export interface CodexAuditResult {
  raw: unknown;
  text: string;
}

function readText(rel: string): string {
  return fs.readFileSync(path.resolve(rel), "utf8");
}

function readJson(rel: string): unknown {
  return JSON.parse(fs.readFileSync(path.resolve(rel), "utf8"));
}

export class CodexAuditAdapter {
  private codex = new Codex({});
  private thread: any | null = null;

  async initialize(): Promise<void> {
    const threadStatePath = path.resolve("state/thread.json");
    const threadState = JSON.parse(fs.readFileSync(threadStatePath, "utf8"));

    // The SDK supports durable thread/session context. The project JSON remains authoritative.
    // If a stored thread cannot be resumed in the installed SDK version/environment,
    // start a new thread without changing project state.
    try {
      if (threadState.codex_thread_id && typeof (this.codex as any).resumeThread === "function") {
        this.thread = await (this.codex as any).resumeThread(threadState.codex_thread_id);
      } else {
        this.thread = await this.codex.startThread();
      }
    } catch {
      this.thread = await this.codex.startThread();
    }

    const id = this.thread?.id ?? null;
    fs.writeFileSync(threadStatePath, JSON.stringify({ codex_thread_id: id }, null, 2) + "\n");
  }

  async runAudit(input: CodexRunInput): Promise<CodexAuditResult> {
    if (!this.thread) await this.initialize();

    const prompt = [
      readText("AGENTS.md"),
      "\n# ACTIVE TASK\n" + JSON.stringify(input.task, null, 2),
      "\n# AUTHORITATIVE PROJECT STATE\n" + JSON.stringify(input.state, null, 2),
      "\n# LOCK REGISTRY\n" + JSON.stringify(input.locks, null, 2),
      "\n# NORMALIZED EVIDENCE PACKAGE\n" + JSON.stringify(input.evidence, null, 2),
      input.revision_feedback?.length
        ? "\n# VALIDATION FEEDBACK TO CORRECT\n" + JSON.stringify(input.revision_feedback, null, 2)
        : "",
      "\nReturn a complete Gridiron Standard audit. Do not mutate files. " +
      "Respect locked baselines. If evidence is insufficient, say so explicitly. " +
      "Include machine-readable JSON in a fenced ```json block and then a concise human-readable audit."
    ].join("\n");

    const result = await this.thread.run(prompt);
    return {
      raw: result,
      text: extractText(result)
    };
  }
}

function extractText(result: any): string {
  if (typeof result === "string") return result;
  if (typeof result?.finalResponse === "string") return result.finalResponse;
  if (typeof result?.output_text === "string") return result.output_text;
  if (typeof result?.text === "string") return result.text;
  return JSON.stringify(result);
}

import fs from "node:fs";
import path from "node:path";
import type { ExternalPlayerRecord, RosterRefreshResult, RosterSource } from "./roster-source.js";

function slug(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");
}

export async function refreshRoster(source: RosterSource): Promise<RosterRefreshResult> {
  const registryPath = path.resolve("data/players/registry.json");
  const registry = JSON.parse(fs.readFileSync(registryPath, "utf8"));
  const current = registry.players as any[];
  const incoming = await source.fetchAllPlayers();

  let added = 0;
  let updated = 0;
  let unchanged = 0;
  const conflicts: Array<Record<string, unknown>> = [];

  const byId = new Map(current.map(p => [p.player_id, p]));

  for (const ext of incoming) {
    const id = ext.source_id ? `ext_${ext.source_id}` : slug(ext.full_name);
    let player = byId.get(id);

    if (!player) {
      // Fallback exact-name match helps preserve history if a future source introduces source IDs.
      const matches = current.filter(p => p.full_name.toLowerCase() === ext.full_name.toLowerCase());
      if (matches.length === 1) player = matches[0];
      if (matches.length > 1) {
        conflicts.push({ type: "DUPLICATE_NAME", external: ext, matches });
        continue;
      }
    }

    if (!player) {
      player = {
        player_id: id,
        full_name: ext.full_name,
        aliases: ext.aliases ?? [],
        team: ext.team,
        position: ext.position,
        historical_positions: ext.position ? [ext.position] : [],
        current_audit_id: null,
        audit_history: [],
        external_ids: {},
        roster_context_history: []
      };
      applySourceMetadata(player, ext as any);
      current.push(player);
      byId.set(player.player_id, player);
      added++;
      continue;
    }

    let changed = false;

    if (ext.team && ext.team !== player.team) {
      player.previous_team = player.team ?? null;
      player.team = ext.team;
      changed = true;
    }

    if (ext.position && ext.position !== player.position) {
      player.historical_positions ??= [];
      if (player.position && !player.historical_positions.includes(player.position)) {
        player.historical_positions.push(player.position);
      }
      if (!player.historical_positions.includes(ext.position)) {
        player.historical_positions.push(ext.position);
      }
      player.position = ext.position;
      changed = true;
    }

    const aliases = new Set([...(player.aliases ?? []), ...(ext.aliases ?? [])]);
    player.aliases = [...aliases];

    if (applySourceMetadata(player, ext as any)) changed = true;

    if (changed) updated++;
    else unchanged++;
  }

  registry.players = current.sort((a,b) => a.full_name.localeCompare(b.full_name));
  registry.last_refreshed_at = new Date().toISOString();

  fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2) + "\n");

  return { added, updated, unchanged, conflicts };
}


function applySourceMetadata(player: any, ext: any): boolean {
  let changed = false;

  player.external_ids ??= {};
  const ids = {
    gsis: ext.gsis_id ?? null,
    espn: ext.espn_id ?? null,
    pff: ext.pff_id ?? null,
    pfr: ext.pfr_id ?? null
  };

  for (const [key, value] of Object.entries(ids)) {
    if (value && player.external_ids[key] !== value) {
      player.external_ids[key] = value;
      changed = true;
    }
  }

  const fields = [
    "jersey_number","roster_status","birth_date","height","weight","college",
    "years_exp","source_position","depth_chart_position","requires_role_resolution",
    "role_resolution_reason"
  ];

  for (const field of fields) {
    const value = ext[field];
    if (value !== undefined && player[field] !== value) {
      player[field] = value;
      changed = true;
    }
  }

  return changed;
}

import fs from "node:fs";
import path from "node:path";
import type { ParsedAudit } from "./audit-parser.js";

export function linkApprovedAuditToPlayer(audit: ParsedAudit): void {
  if (!audit.player_id) throw new Error("Approved audit missing player_id.");

  const registryPath = path.resolve("data/players/registry.json");
  const registry = JSON.parse(fs.readFileSync(registryPath, "utf8"));
  const player = registry.players.find((p: any) => p.player_id === audit.player_id);

  if (!player) throw new Error(`Unknown player_id: ${audit.player_id}`);

  player.audit_history ??= [];
  if (!player.audit_history.includes(audit.audit_id)) {
    player.audit_history.push(audit.audit_id);
  }
  player.current_audit_id = audit.audit_id;

  fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2) + "\n");

  const dir = path.resolve("data/players", audit.player_id);
  fs.mkdirSync(dir, { recursive: true });

  const snapshot = {
    player_id: audit.player_id,
    current_audit_id: audit.audit_id,
    position: audit.position,
    ovr: audit.ovr_after ?? null,
    ratings: audit.ratings ?? {},
    approved_at: audit.created_at,
    methodology_version: audit.methodology_version
  };

  fs.writeFileSync(
    path.join(dir, "current.json"),
    JSON.stringify(snapshot, null, 2) + "\n"
  );
}

export function getCurrentApprovedCard(playerId: string): Record<string, unknown> | null {
  const file = path.resolve("data/players", playerId, "current.json");
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

import fs from "node:fs";
import { buildPlayerAuditTask } from "./player-audit-task.js";
import { loadBaselineControls } from "./baseline-controls.js";
import { CodexResearchAdapter } from "./codex-research.js";
import { CodexAuditAdapter } from "./codex-adapter.js";
import { parseAuditJson } from "./audit-parser.js";
import { validateAudit } from "./audit-validator.js";
import { saveAuditRecord, queueReaudit } from "./persistence.js";
import { linkApprovedAuditToPlayer, getCurrentApprovedCard } from "./player-history.js";
import type { PlayerIdentity } from "./player-resolver.js";

const MAX_REVISIONS = Number(process.env.GRIDIRON_MAX_REVISIONS ?? "3");

export async function executePlayerAudit(player: PlayerIdentity): Promise<Record<string, unknown>> {
  const task = buildPlayerAuditTask(player);
  const controls = loadBaselineControls(task.position);
  const locks = JSON.parse(fs.readFileSync("state/locks.json", "utf8"));
  const state = JSON.parse(fs.readFileSync("state/project-state.json", "utf8"));
  const previousCard = getCurrentApprovedCard(player.player_id);

  const research = new CodexResearchAdapter();
  const evidence = await research.gather({
    ...task,
    baseline_controls: {
      top_10: controls.top_10,
      first_out: controls.first_out,
      external_controls: controls.external_controls
    },
    previous_card: previousCard
  });

  if (!evidence.minimum_evidence_met) {
    const record = {
      audit_id: `${task.task_id}_INSUFFICIENT`,
      audit_type: "FULL_AUDIT",
      status: "INSUFFICIENT_EVIDENCE",
      player_id: player.player_id,
      position: task.position,
      confidence: "LOW",
      methodology_version: state.methodology_version,
      created_at: new Date().toISOString(),
      missing_evidence: evidence.missing_evidence,
      sources: evidence.sources
    };

    saveAuditRecord(record as any, renderMarkdown(record));
    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "INSUFFICIENT_EVIDENCE",
      player_id: player.player_id,
      audit_id: record.audit_id,
      created_at: new Date().toISOString()
    });
    return record;
  }

  const analyst = new CodexAuditAdapter();
  let feedback: string[] = [];
  let parsed: any = null;
  let validation: any = null;
  let responseText = "";

  for (let attempt = 1; attempt <= MAX_REVISIONS; attempt++) {
    const result = await analyst.runAudit({
      task: {
        ...task,
        requirements: {
          use_locked_top10_as_primary_reference: true,
          use_nearest_external_controls: true,
          why_not_higher_required: true,
          why_not_lower_required: true,
          player_identity_required: true,
          challenger_flag_required_if_close: true,
          may_not_mutate_locked_top10: true
        },
        baseline_controls: controls,
        previous_card: previousCard
      },
      evidence,
      state,
      locks,
      revision_feedback: feedback
    });

    responseText = result.text;
    parsed = parseAuditJson(result.text);

    // Canonical identity fields are application-controlled.
    parsed.player_id = player.player_id;
    parsed.position = task.position;
    parsed.audit_type = "FULL_AUDIT";
    parsed.methodology_version = state.methodology_version;
    parsed.created_at ??= new Date().toISOString();

    validation = validateAudit(parsed);

    // Structural Gridiron requirements for one-off player audits.
    if (!Array.isArray(parsed.nearest_controls) || parsed.nearest_controls.length === 0) {
      validation.errors.push("Missing nearest_controls.");
      validation.valid = false;
    }
    if (!parsed.player_identity) {
      validation.errors.push("Missing player_identity.");
      validation.valid = false;
    }
    if (!parsed.why_not_higher) {
      validation.errors.push("Missing why_not_higher.");
      validation.valid = false;
    }
    if (!parsed.why_not_lower) {
      validation.errors.push("Missing why_not_lower.");
      validation.valid = false;
    }

    if (validation.valid) break;
    feedback = validation.errors;
  }

  if (!validation?.valid) {
    parsed.status = "FLAGGED";
    parsed.major_flags = [...new Set([...(parsed.major_flags ?? []), "RE-AUDIT REQUIRED"])];
    saveAuditRecord(parsed, responseText || renderMarkdown(parsed));
    queueReaudit({
      severity: "RE-AUDIT REQUIRED",
      reason: "VALIDATION_FAILED_AFTER_3_ATTEMPTS",
      player_id: player.player_id,
      audit_id: parsed.audit_id,
      created_at: new Date().toISOString()
    });
    return parsed;
  }

  parsed.major_flags = [...new Set([...(parsed.major_flags ?? []), ...validation.flags])];
  parsed.status = validation.auto_approve ? "APPROVED" : (parsed.major_flags.length ? "FLAGGED" : "VALIDATED");

  saveAuditRecord(parsed, responseText);

  if (parsed.status === "APPROVED") {
    linkApprovedAuditToPlayer(parsed);
  } else if (parsed.status === "FLAGGED") {
    queueReaudit({
      severity: parsed.challenger_flag ? "RE-AUDIT REQUIRED" : "REVIEW",
      reason: parsed.major_flags,
      player_id: player.player_id,
      audit_id: parsed.audit_id,
      challenger_flag: parsed.challenger_flag ?? false,
      created_at: new Date().toISOString()
    });
  }

  return parsed;
}

function renderMarkdown(record: Record<string, unknown>): string {
  return `# ${record.audit_id}\n\nStatus: ${record.status}\n\n\`\`\`json\n${JSON.stringify(record, null, 2)}\n\`\`\``;
}

