import fs from "node:fs";
import path from "node:path";
import { findTeamPlayers } from "./player-resolver.js";
import { executePlayerAudit } from "./player-executor.js";

export interface BulkAuditOptions {
  team: string;
  position?: string;
}

export interface BulkAuditItem {
  player_id: string;
  player: string;
  position: string | null;
  status: string;
  audit_id?: string | null;
  major_flags?: string[];
  challenger_flag?: boolean;
  reason?: string;
}

export interface BulkAuditResult {
  batch_id: string;
  team: string;
  position: string | null;
  started_at: string;
  completed_at: string;
  players_total: number;
  players_processed: number;
  approved: number;
  flagged: number;
  insufficient_evidence: number;
  unresolved_position: number;
  failed: number;
  items: BulkAuditItem[];
  review_report_file: string;
}

export async function executeTeamBulkAudit(
  options: BulkAuditOptions
): Promise<BulkAuditResult> {
  const team = options.team.toUpperCase();
  const position = options.position?.toUpperCase();

  const players = findTeamPlayers(team, position);
  const startedAt = new Date().toISOString();
  const batchId =
    `TEAM_${team}_${position ?? "ALL"}_${startedAt.replace(/[:.]/g, "-")}`;

  const items: BulkAuditItem[] = [];

  for (const player of players) {
    if (!player.position) {
      items.push({
        player_id: player.player_id,
        player: player.full_name,
        position: null,
        status: "UNRESOLVED_POSITION",
        reason: "Exact Madden position must be resolved before Full Audit."
      });
      continue;
    }

    try {
      const result: any = await executePlayerAudit(player);

      items.push({
        player_id: player.player_id,
        player: player.full_name,
        position: player.position,
        status: String(result.status ?? "UNKNOWN"),
        audit_id: result.audit_id ?? null,
        major_flags: result.major_flags ?? [],
        challenger_flag: Boolean(result.challenger_flag)
      });
    } catch (error) {
      items.push({
        player_id: player.player_id,
        player: player.full_name,
        position: player.position,
        status: "FAILED",
        reason: error instanceof Error ? error.message : String(error)
      });
    }
  }

  const completedAt = new Date().toISOString();

  const result: BulkAuditResult = {
    batch_id: batchId,
    team,
    position: position ?? null,
    started_at: startedAt,
    completed_at: completedAt,
    players_total: players.length,
    players_processed: items.length,
    approved: items.filter(x => x.status === "APPROVED").length,
    flagged: items.filter(x => x.status === "FLAGGED" || (x.major_flags?.length ?? 0) > 0).length,
    insufficient_evidence: items.filter(x => x.status === "INSUFFICIENT_EVIDENCE").length,
    unresolved_position: items.filter(x => x.status === "UNRESOLVED_POSITION").length,
    failed: items.filter(x => x.status === "FAILED").length,
    items,
    review_report_file: ""
  };

  const reportPath = saveBatchReport(result);
  result.review_report_file = reportPath;

  const jsonPath = path.resolve("audits/teams", team, `${batchId}.json`);
  fs.mkdirSync(path.dirname(jsonPath), { recursive: true });
  fs.writeFileSync(jsonPath, JSON.stringify(result, null, 2) + "\n");

  return result;
}

function saveBatchReport(result: BulkAuditResult): string {
  const dir = path.resolve("audits/teams", result.team);
  fs.mkdirSync(dir, { recursive: true });

  const file = path.join(dir, `${result.batch_id}-review.md`);

  const reviewItems = result.items.filter(item =>
    item.status === "FLAGGED" ||
    item.status === "INSUFFICIENT_EVIDENCE" ||
    item.status === "UNRESOLVED_POSITION" ||
    item.status === "FAILED" ||
    (item.major_flags?.length ?? 0) > 0
  );

  const lines: string[] = [
    `# ${result.team}${result.position ? ` ${result.position}` : ""} Bulk Audit Review`,
    "",
    `Batch: ${result.batch_id}`,
    `Started: ${result.started_at}`,
    `Completed: ${result.completed_at}`,
    "",
    "## Summary",
    "",
    `- Total players: ${result.players_total}`,
    `- Approved: ${result.approved}`,
    `- Flagged: ${result.flagged}`,
    `- Insufficient evidence: ${result.insufficient_evidence}`,
    `- Unresolved positions: ${result.unresolved_position}`,
    `- Failed: ${result.failed}`,
    "",
    "## Review Queue",
    ""
  ];

  if (!reviewItems.length) {
    lines.push("No flagged or unresolved cases.");
  } else {
    for (const item of reviewItems) {
      const severity = item.challenger_flag
        ? "RE-AUDIT REQUIRED"
        : item.status === "FAILED"
          ? "RE-AUDIT REQUIRED"
          : item.status === "INSUFFICIENT_EVIDENCE"
            ? "REVIEW"
            : item.status === "UNRESOLVED_POSITION"
              ? "REVIEW"
              : "REVIEW";

      lines.push(`### ${item.player}`);
      lines.push("");
      lines.push(`- Severity: ${severity}`);
      lines.push(`- Position: ${item.position ?? "UNRESOLVED"}`);
      lines.push(`- Status: ${item.status}`);
      if (item.audit_id) lines.push(`- Audit ID: ${item.audit_id}`);
      if (item.major_flags?.length) {
        lines.push(`- Flags: ${item.major_flags.join(", ")}`);
      }
      if (item.reason) lines.push(`- Reason: ${item.reason}`);
      lines.push("");
    }
  }

  fs.writeFileSync(file, lines.join("\n") + "\n");
  return file;
}

import fs from "node:fs";
import path from "node:path";
import type { ExportRecord, ExportMode } from "./export-types.js";

function csvEscape(value: unknown): string {
  const text = value == null ? "" : String(value);
  if (/[",\n]/.test(text)) return `"${text.replace(/"/g, '""')}"`;
  return text;
}

function loadOrder(): any {
  return JSON.parse(fs.readFileSync(path.resolve("config/madden-entry-order.json"), "utf8"));
}

export function writeExport(
  records: ExportRecord[],
  mode: ExportMode,
  label: string
): { csv: string; json: string } {
  const dir = path.resolve("exports");
  fs.mkdirSync(dir, { recursive: true });

  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const safeLabel = label.replace(/[^a-zA-Z0-9._-]+/g, "_");
  const base = `${safeLabel}_${mode}_${stamp}`;

  const jsonPath = path.join(dir, `${base}.json`);
  const csvPath = path.join(dir, `${base}.csv`);

  fs.writeFileSync(jsonPath, JSON.stringify(records, null, 2) + "\n");

  const csv = mode === "MADDEN_ENTRY"
    ? renderMaddenEntryCsv(records)
    : renderRichCsv(records);

  fs.writeFileSync(csvPath, csv);

  return { csv: csvPath, json: jsonPath };
}

function renderMaddenEntryCsv(records: ExportRecord[]): string {
  const orderConfig = loadOrder();
  const allAttrs = new Set<string>();

  for (const record of records) {
    const posOrder = orderConfig.positions?.[record.position ?? ""] ?? [];
    for (const attr of posOrder) {
      if (attr !== "OVR") allAttrs.add(attr);
    }
    for (const attr of Object.keys(record.ratings ?? {})) allAttrs.add(attr);
  }

  const attrs = [...allAttrs];
  const headers = ["Player","Team","Position","OVR",...attrs];

  const rows = records.map(record => {
    const values: unknown[] = [
      record.player,
      record.team ?? "",
      record.position ?? "",
      record.ovr ?? ""
    ];
    for (const attr of attrs) {
      values.push(record.ratings?.[attr] ?? "");
    }
    return values.map(csvEscape).join(",");
  });

  return [headers.join(","), ...rows].join("\n") + "\n";
}

function renderRichCsv(records: ExportRecord[]): string {
  const allAttrs = new Set<string>();
  for (const record of records) {
    for (const attr of Object.keys(record.ratings ?? {})) allAttrs.add(attr);
  }
  const attrs = [...allAttrs].sort();

  const headers = [
    "Player","Player ID","Team","Position","OVR",
    "Audit ID","Audit Status","Confidence","Methodology Version",
    "Audit Date","Archetype/Identity","Flags",
    ...attrs
  ];

  const rows = records.map(record => {
    const values: unknown[] = [
      record.player,
      record.player_id,
      record.team ?? "",
      record.position ?? "",
      record.ovr ?? "",
      record.audit_id ?? "",
      record.status ?? "",
      record.confidence ?? "",
      record.methodology_version ?? "",
      record.audit_date ?? "",
      record.archetype ?? "",
      (record.flags ?? []).join("|")
    ];
    for (const attr of attrs) values.push(record.ratings?.[attr] ?? "");
    return values.map(csvEscape).join(",");
  });

  return [headers.join(","), ...rows].join("\n") + "\n";
}

import fs from "node:fs";
import path from "node:path";
import { resolvePlayer } from "./player-resolver.js";
import { getCurrentApprovedCard } from "./player-history.js";

interface OrderedRating {
  attribute: string;
  rating: number;
  order: number;
}

function readJson(rel: string): any {
  return JSON.parse(fs.readFileSync(path.resolve(rel), "utf8"));
}

function getTeamBranding(team: string | null): any {
  const config = readJson("config/team-branding.json");
  if (!team) return config.fallback;
  return config.teams?.[team.toUpperCase()] ?? config.fallback;
}

function getMaddenOrder(position: string): string[] {
  const orderConfig = readJson("config/madden-entry-order.json");
  return orderConfig.positions?.[position] ?? [];
}

export function buildInputCardSpec(query: string): Record<string, unknown> {
  const resolution = resolvePlayer(query);

  if (resolution.status !== "RESOLVED" || !resolution.player) {
    return resolution;
  }

  const player = resolution.player;
  const current = getCurrentApprovedCard(player.player_id);

  if (!current) {
    return {
      status: "FULL_AUDIT_REQUIRED",
      player_id: player.player_id,
      player: player.full_name,
      reason: "No approved current card exists."
    };
  }

  const outputPolicy = readJson("config/output-policy.json");
  const position = String(current.position ?? player.position ?? "");
  const order = getMaddenOrder(position);
  const ratings = current.ratings ?? {};

  const orderedRatings: OrderedRating[] = order
    .filter((attribute: string) => attribute !== "OVR")
    .filter((attribute: string) => typeof ratings[attribute] === "number")
    .map((attribute: string, index: number) => ({
      attribute,
      rating: Number(ratings[attribute]),
      order: index + 1
    }));

  for (const attribute of Object.keys(ratings)) {
    if (!order.includes(attribute)) {
      orderedRatings.push({
        attribute,
        rating: Number(ratings[attribute]),
        order: orderedRatings.length + 1
      });
    }
  }

  const branding = getTeamBranding(player.team ?? null);

  const spec = {
    status: "OK",
    player_id: player.player_id,
    player_name: player.full_name,
    team: player.team ?? null,
    team_name: branding.display_name ?? player.team ?? "NFL Team",
    position,
    ovr: Number(current.ovr),
    ordered_ratings: orderedRatings,
    branding,
    include_player_photo: false,
    output_policy_version: outputPolicy.version,
    card_style: outputPolicy.graphic_input_card.style,
    explicit_request_required: outputPolicy.graphic_input_card.generate_only_on_explicit_request
  };

  saveCardSpec(spec);
  return spec;
}

function saveCardSpec(spec: Record<string, unknown>): void {
  const dir = path.resolve("exports/cards");
  fs.mkdirSync(dir, { recursive: true });
  const playerId = String(spec.player_id);
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const file = path.join(dir, `${playerId}_${stamp}.json`);
  fs.writeFileSync(file, JSON.stringify(spec, null, 2) + "\n");
}

import http from "node:http";
import { URL } from "node:url";
import { loadState } from "./state.js";
import { buildInputCardSpec } from "./card-spec.js";
import { resolvePlayer } from "./player-resolver.js";
import { ratingsOnly } from "./ratings-only.js";
import { healthReport } from "./health.js";

const PORT = Number(process.env.PORT ?? "3000");

function sendJson(res: http.ServerResponse, status: number, data: unknown): void {
  res.statusCode = status;
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  res.end(JSON.stringify(data, null, 2));
}

const server = http.createServer((req, res) => {
  try {
    const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

    if (req.method === "GET" && url.pathname === "/health") {
      return sendJson(res, 200, healthReport());
    }

    if (req.method === "GET" && url.pathname === "/status") {
      return sendJson(res, 200, loadState());
    }

    if (req.method === "GET" && url.pathname === "/player/card") {
      const name = url.searchParams.get("name");
      if (!name) return sendJson(res, 400, { error: "Missing name query parameter." });
      return sendJson(res, 200, buildInputCardSpec(name));
    }

    if (req.method === "GET" && url.pathname === "/player/ratings") {
      const name = url.searchParams.get("name");
      if (!name) return sendJson(res, 400, { error: "Missing name query parameter." });
      const resolved = resolvePlayer(name);
      if (resolved.status !== "RESOLVED" || !resolved.player) {
        return sendJson(res, 404, resolved);
      }
      return sendJson(res, 200, ratingsOnly(resolved.player));
    }

    return sendJson(res, 404, { error: "Not found." });
  } catch (error) {
    return sendJson(res, 500, {
      error: "Internal server error.",
      detail: error instanceof Error ? error.message : String(error)
    });
  }
});

server.listen(PORT, () => {
  console.log(`Gridiron Standard server listening on port ${PORT}`);
});

export function assertTop10MutationAllowed(
  baselineStatus: string,
  intent: string
): void {
  if (baselineStatus === "LOCKED" && intent !== "TOP10_REAUDIT") {
    throw new Error(
      "LOCK VIOLATION: Locked Top 10 baseline may only be changed by explicit TOP10_REAUDIT."
    );
  }
}

export interface ParsedAudit {
  audit_id: string;
  audit_type: string;
  status: string;
  player_id?: string;
  position: string;
  confidence: "HIGH" | "MEDIUM" | "LOW";
  methodology_version: string;
  created_at: string;
  ovr_before?: number | null;
  ovr_after?: number | null;
  ratings?: Record<string, number>;
  challenger_flag?: boolean;
  nearest_controls?: string[];
  major_flags?: string[];
  added_95_plus?: boolean;
  removed_95_plus?: boolean;
  changed_97_plus_or_99?: boolean;
  major_position_change?: boolean;
  locked_control_conflict?: boolean;
  material_attribute_redistribution?: boolean;
  sources?: unknown[];
  [key: string]: unknown;
}

export function parseAuditJson(text: string): ParsedAudit {
  const fenced = text.match(/```json\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : text;
  const start = candidate.indexOf("{");
  const end = candidate.lastIndexOf("}");
  if (start < 0 || end < 0) throw new Error("Audit output contains no JSON object.");
  return JSON.parse(candidate.slice(start, end + 1)) as ParsedAudit;
}

