import fs from "node:fs";
import path from "node:path";

export interface PlayerIdentity {
  player_id: string;
  full_name: string;
  aliases: string[];
  team: string | null;
  position: string | null;
  historical_positions: string[];
  current_audit_id: string | null;
  audit_history: string[];
}

export interface Resolution {
  status: "RESOLVED" | "AMBIGUOUS" | "NOT_FOUND";
  player?: PlayerIdentity;
  candidates?: PlayerIdentity[];
  query: string;
}

function normalize(value: string): string {
  return value
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function loadRegistry(): PlayerIdentity[] {
  const file = path.resolve("data/players/registry.json");
  const data = JSON.parse(fs.readFileSync(file, "utf8"));
  return data.players as PlayerIdentity[];
}

export function resolvePlayer(
  query: string,
  team?: string,
  position?: string
): Resolution {
  const q = normalize(query);
  const players = loadRegistry();

  const scored = players
    .map(player => {
      const names = [
        player.full_name,
        ...(player.aliases ?? [])
      ].map(normalize);

      let score = 0;
      if (names.includes(q)) score += 100;
      if (normalize(player.full_name).endsWith(" " + q)) score += 70;
      if (normalize(player.full_name).startsWith(q + " ")) score += 50;
      if (normalize(player.full_name).includes(q)) score += 30;

      if (team && player.team?.toUpperCase() === team.toUpperCase()) score += 20;
      if (position && player.position === position.toUpperCase()) score += 20;

      return { player, score };
    })
    .filter(x => x.score > 0)
    .sort((a,b) => b.score - a.score);

  if (!scored.length) return { status: "NOT_FOUND", query };

  const top = scored[0].score;
  const tied = scored.filter(x => x.score === top).map(x => x.player);

  if (tied.length > 1) {
    return { status: "AMBIGUOUS", query, candidates: tied };
  }

  return { status: "RESOLVED", query, player: tied[0] };
}

export function findTeamPlayers(team: string, position?: string): PlayerIdentity[] {
  return loadRegistry().filter(p =>
    p.team?.toUpperCase() === team.toUpperCase() &&
    (!position || p.position === position.toUpperCase())
  );
}

import fs from "node:fs";
import path from "node:path";
import type { ExportRequest, ExportRecord } from "./export-types.js";

function loadRegistry(): any[] {
  const file = path.resolve("data/players/registry.json");
  return JSON.parse(fs.readFileSync(file, "utf8")).players ?? [];
}

function loadCurrentCard(playerId: string): any | null {
  const file = path.resolve("data/players", playerId, "current.json");
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function loadAudit(position: string | null, auditId: string | null): any | null {
  if (!position || !auditId) return null;
  const file = path.resolve("audits/league", position, `${auditId}.json`);
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

export function collectExportRecords(request: ExportRequest): ExportRecord[] {
  const players = loadRegistry();

  const filtered = players.filter(player => {
    if (request.scope === "PLAYER") return player.player_id === request.player_id;
    if (request.scope === "POSITION") return player.position === request.position;
    if (request.scope === "TEAM") {
      if (player.team?.toUpperCase() !== request.team?.toUpperCase()) return false;
      if (request.position && player.position !== request.position) return false;
      return true;
    }
    return true;
  });

  const records: ExportRecord[] = [];

  for (const player of filtered) {
    const current = loadCurrentCard(player.player_id);

    if (!current) {
      if (!request.include_nonapproved) continue;
      records.push({
        player_id: player.player_id,
        player: player.full_name,
        team: player.team ?? null,
        position: player.position ?? null,
        ovr: null,
        ratings: {},
        audit_id: null,
        methodology_version: null,
        status: "NO_APPROVED_CURRENT_CARD",
        flags: []
      });
      continue;
    }

    const audit = loadAudit(current.position ?? player.position, current.current_audit_id ?? null);

    records.push({
      player_id: player.player_id,
      player: player.full_name,
      team: player.team ?? null,
      position: current.position ?? player.position ?? null,
      ovr: current.ovr ?? null,
      ratings: current.ratings ?? {},
      audit_id: current.current_audit_id ?? null,
      methodology_version: current.methodology_version ?? null,
      confidence: audit?.confidence ?? null,
      status: audit?.status ?? "APPROVED",
      archetype: audit?.archetype ?? audit?.player_identity ?? null,
      audit_date: audit?.created_at ?? current.approved_at ?? null,
      flags: audit?.major_flags ?? []
    });
  }

  return records;
}

import fs from "node:fs";
import path from "node:path";
import type { ParsedAudit } from "./audit-parser.js";

function safe(value: string): string {
  return value.replace(/[^a-zA-Z0-9._-]+/g, "_");
}

export function saveAuditRecord(audit: ParsedAudit, markdown: string): { json: string; md: string } {
  const pos = safe(audit.position);
  const dir = path.resolve("audits/league", pos);
  fs.mkdirSync(dir, { recursive: true });

  const id = safe(audit.audit_id);
  const jsonPath = path.join(dir, `${id}.json`);
  const mdPath = path.join(dir, `${id}.md`);

  // Immutable history: never overwrite an existing audit.
  if (fs.existsSync(jsonPath) || fs.existsSync(mdPath)) {
    throw new Error(`Immutable audit already exists: ${audit.audit_id}`);
  }

  fs.writeFileSync(jsonPath, JSON.stringify(audit, null, 2) + "\n");
  fs.writeFileSync(mdPath, markdown.trim() + "\n");
  return { json: jsonPath, md: mdPath };
}

export function queueReaudit(item: Record<string, unknown>): void {
  const statePath = path.resolve("state/project-state.json");
  const state = JSON.parse(fs.readFileSync(statePath, "utf8"));
  state.pending_reaudit_queue ??= [];
  state.pending_reaudit_queue.push(item);
  fs.writeFileSync(statePath, JSON.stringify(state, null, 2) + "\n");
}

import fs from "node:fs";
import path from "node:path";

type Check = { name: string; ok: boolean; detail?: string };

function exists(rel: string): boolean {
  return fs.existsSync(path.resolve(rel));
}

function readJson(rel: string): any {
  return JSON.parse(fs.readFileSync(path.resolve(rel), "utf8"));
}

const checks: Check[] = [];

for (const rel of [
  "AGENTS.md",
  "state/project-state.json",
  "state/locks.json",
  "data/players/registry.json",
  "config/output-policy.json",
  "config/team-branding.json",
  "config/madden-entry-order.json"
]) {
  checks.push({
    name: `file:${rel}`,
    ok: exists(rel),
    detail: exists(rel) ? undefined : "missing"
  });
}

try {
  const state = readJson("state/project-state.json");
  checks.push({
    name: "architecture_version",
    ok: state.architecture_version === "1.0.0",
    detail: String(state.architecture_version)
  });
  checks.push({
    name: "review_mode",
    ok: state.review_mode === "REVIEW_MAJOR",
    detail: String(state.review_mode)
  });
} catch (error) {
  checks.push({
    name: "project_state_parse",
    ok: false,
    detail: error instanceof Error ? error.message : String(error)
  });
}

try {
  const policy = readJson("config/output-policy.json");
  checks.push({
    name: "card_photo_disabled",
    ok: policy.graphic_input_card?.include_player_photo === false
  });
  checks.push({
    name: "card_requires_explicit_request",
    ok: policy.graphic_input_card?.generate_only_on_explicit_request === true
  });
} catch (error) {
  checks.push({
    name: "output_policy_parse",
    ok: false,
    detail: error instanceof Error ? error.message : String(error)
  });
}

try {
  const order = readJson("config/madden-entry-order.json");
  checks.push({
    name: "madden_order_registry_present",
    ok: Boolean(order.positions)
  });
  checks.push({
    name: "madden_order_verified",
    ok: order.verified === true,
    detail: order.verified === true
      ? "verified"
      : "NOT VERIFIED: deployment may serve ratings, but production graphic card generation should remain gated."
  });
} catch (error) {
  checks.push({
    name: "madden_order_parse",
    ok: false,
    detail: error instanceof Error ? error.message : String(error)
  });
}

const failed = checks.filter(x => !x.ok);
console.log(JSON.stringify({
  status: failed.length ? "FAIL" : "PASS",
  checks
}, null, 2));

if (failed.some(x => x.name !== "madden_order_verified")) {
  process.exitCode = 1;
}

import { resolvePlayer, findTeamPlayers } from "./player-resolver.js";
import type { Intent } from "./router.js";

export function resolveIntent(intent: Intent): Record<string, unknown> {
  if (intent.type === "FULL_PLAYER_AUDIT" ||
      intent.type === "RATINGS_ONLY" ||
      intent.type === "QUICK_RECHECK") {
    const resolution = resolvePlayer(intent.query);

    if (resolution.status === "NOT_FOUND") {
      return {
        status: "NEEDS_ROSTER_REFRESH",
        reason: "PLAYER_NOT_FOUND",
        query: intent.query
      };
    }

    if (resolution.status === "AMBIGUOUS") {
      return {
        status: "AMBIGUOUS",
        query: intent.query,
        candidates: resolution.candidates
      };
    }

    return {
      status: "RESOLVED",
      intent: intent.type,
      player: resolution.player
    };
  }

  return { status: "PASS_THROUGH", intent };
}

export function resolveTeamQuery(team: string, position?: string): Record<string, unknown> {
  const players = findTeamPlayers(team, position);
  return {
    status: players.length ? "RESOLVED" : "NEEDS_ROSTER_REFRESH",
    team: team.toUpperCase(),
    position: position?.toUpperCase() ?? null,
    players
  };
}

