import fs from "node:fs";
import path from "node:path";
import type { PlayerIdentity } from "./player-resolver.js";

export interface PlayerAuditTask {
  task_id: string;
  type: "player_full_audit";
  audit_type: "FULL_AUDIT";
  player_id: string;
  player_name: string;
  team: string | null;
  position: string;
  locked_baseline_file: string;
  current_audit_id: string | null;
}

export function buildPlayerAuditTask(player: PlayerIdentity): PlayerAuditTask {
  if (!player.position) {
    throw new Error(
      `PLAYER_POSITION_UNRESOLVED: ${player.full_name} requires exact Madden position resolution before Full Audit.`
    );
  }

  const baselinePath = path.resolve(`data/baselines/${player.position}.json`);
  if (!fs.existsSync(baselinePath)) {
    throw new Error(
      `BASELINE_NOT_AVAILABLE: ${player.position} does not yet have a positional baseline file.`
    );
  }

  const baseline = JSON.parse(fs.readFileSync(baselinePath, "utf8"));
  if (baseline.status !== "LOCKED") {
    throw new Error(
      `BASELINE_NOT_LOCKED: ${player.position} must have a locked Top 10 before one-off player audits can use it as authoritative calibration.`
    );
  }

  const safe = player.player_id.replace(/[^a-zA-Z0-9._-]+/g, "_");
  return {
    task_id: `PLAYER_${safe}_${Date.now()}`,
    type: "player_full_audit",
    audit_type: "FULL_AUDIT",
    player_id: player.player_id,
    player_name: player.full_name,
    team: player.team ?? null,
    position: player.position,
    locked_baseline_file: `data/baselines/${player.position}.json`,
    current_audit_id: player.current_audit_id ?? null
  };
}

import fs from "node:fs";
import path from "node:path";
import { findTeamPlayers } from "./player-resolver.js";
import { getCurrentApprovedCard } from "./player-history.js";

export function createTeamRoomSnapshot(team: string, position: string): Record<string, unknown> {
  const players = findTeamPlayers(team.toUpperCase(), position.toUpperCase());

  const unresolved = players.filter(p => !getCurrentApprovedCard(p.player_id));
  if (unresolved.length) {
    throw new Error(
      `TEAM_ROOM_NOT_READY: ${unresolved.length} player(s) lack approved current cards.`
    );
  }

  const snapshot = {
    team: team.toUpperCase(),
    position: position.toUpperCase(),
    status: "LOCKED",
    locked_at: new Date().toISOString(),
    players: players.map(player => ({
      player_id: player.player_id,
      full_name: player.full_name,
      current_card: getCurrentApprovedCard(player.player_id)
    })),
    mutation_policy: "IMMUTABLE_UNTIL_EXPLICIT_TEAM_ROOM_REAUDIT"
  };

  const dir = path.resolve("data/teams", team.toUpperCase(), "rooms", position.toUpperCase());
  fs.mkdirSync(dir, { recursive: true });

  const versionFile = path.join(
    dir,
    `snapshot_${snapshot.locked_at.replace(/[:.]/g, "-")}.json`
  );
  const currentFile = path.join(dir, "current.json");

  fs.writeFileSync(versionFile, JSON.stringify(snapshot, null, 2) + "\n");
  fs.writeFileSync(currentFile, JSON.stringify(snapshot, null, 2) + "\n");

  return snapshot;
}

import fs from "node:fs";
import path from "node:path";
import { majorFlags, mayAutoApprove } from "./validator.js";
import type { ParsedAudit } from "./audit-parser.js";

export interface ValidationResult {
  valid: boolean;
  auto_approve: boolean;
  errors: string[];
  flags: string[];
}

export function validateAudit(audit: ParsedAudit): ValidationResult {
  const errors: string[] = [];
  const ratings = audit.ratings ?? {};

  for (const [attribute, rating] of Object.entries(ratings)) {
    if (!Number.isInteger(rating) || rating < 0 || rating > 99) {
      errors.push(`Invalid rating ${attribute}=${rating}.`);
    }
  }

  if (!audit.position) errors.push("Missing position.");
  if (!audit.confidence) errors.push("Missing confidence.");
  if (!audit.methodology_version) errors.push("Missing methodology_version.");

  const flags = majorFlags({
    audit_type: audit.audit_type,
    confidence: audit.confidence,
    ovr_before: audit.ovr_before,
    ovr_after: audit.ovr_after,
    challenger_flag: audit.challenger_flag,
    added_95_plus: audit.added_95_plus,
    removed_95_plus: audit.removed_95_plus,
    changed_97_plus_or_99: audit.changed_97_plus_or_99,
    major_position_change: audit.major_position_change,
    locked_control_conflict: audit.locked_control_conflict
  });

  // Locked baseline mutation is prohibited outside explicit Top 10 re-audit.
  const locksPath = path.resolve("state/locks.json");
  const locks = JSON.parse(fs.readFileSync(locksPath, "utf8"));
  const lock = locks.positions?.[audit.position];
  if (lock?.status === "LOCKED" && audit.audit_type !== "TOP10_REAUDIT") {
    if ((audit as any).proposed_top10_mutation === true) {
      errors.push("LOCK VIOLATION: normal audit attempted Top 10 mutation.");
    }
  }

  return {
    valid: errors.length === 0,
    auto_approve: errors.length === 0 && mayAutoApprove({
      audit_type: audit.audit_type,
      confidence: audit.confidence,
      ovr_before: audit.ovr_before,
      ovr_after: audit.ovr_after,
      challenger_flag: audit.challenger_flag,
      added_95_plus: audit.added_95_plus,
      removed_95_plus: audit.removed_95_plus,
      changed_97_plus_or_99: audit.changed_97_plus_or_99,
      major_position_change: audit.major_position_change,
      locked_control_conflict: audit.locked_control_conflict
    }),
    errors,
    flags
  };
}

